insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('schdiftungsroot', 'Schdiftungsroot', '', '', '', '', 'Stiftungsrat', '[{"kategorie": "allg.", "text": "\"optionales Kontroll- und Aufsichtsorgan in österreichischen [[Stiftungen]], das eingerichtet werden kann, um den [[Stiftungsvorstand]] zu überwachen und die ordnungsgemäße Umsetzung des Stiftungszwecks sicherzustellen\""}, {"kategorie": "", "text": "In einer [[Privatstiftung]] ist der Stiftungsrat dann verpflichtend, wenn die Stiftung mehr als 300 Mitarbeiter beschäftigt oder wenn das Stiftungskapital eine bestimmte Höhe überschreitet"}, {"kategorie": "", "text": "Der Stiftungsrat wird vom Stifter eingerichtet und hat das Ziel, die Interessen des Stifters sowie der Begünstigten zu wahren"}, {"kategorie": "", "text": "Aufgaben und Funktionen des Stiftungsrats:  (i) Überwachung des [[Stiftungsvorstands]]: Der Stiftungsrat kontrolliert die Tätigkeit des Stiftungsvorstands, um sicherzustellen, dass dieser die Stiftungsgeschäfte ordnungsgemäß und gemäß dem Stiftungszweck führt;  (ii) Genehmigungspflichtige Geschäfte: In manchen Stiftungen muss der Stiftungsvorstand bestimmte Geschäfte oder Entscheidungen vom Stiftungsrat genehmigen lassen, insbesondere wenn es sich um wesentliche oder ungewöhnliche Geschäfte handelt;  (iii) Prüfung und Berichterstattung: Der Stiftungsrat prüft die Berichte des Stiftungsvorstands, insbesondere den Jahresabschluss und die Verwendung der Stiftungsmittel. Er stellt sicher, dass alle Tätigkeiten im Einklang mit dem Stiftungszweck und den gesetzlichen Vorgaben stehen;  (iv) Wahrung der Stifterinteressen: Der Stiftungsrat hat die Aufgabe, die Interessen des Stifters und der Begünstigten zu wahren und sicherzustellen, dass das Stiftungsvermögen im Sinne des Stifters verwendet wird"}, {"kategorie": "", "text": "Die Mitglieder des Stiftungsrats werden in der Regel vom Stifter bestimmt oder in der [[Stiftungsurkunde]] festgelegt. In vielen Fällen können auch Begünstigte oder deren Vertreter im Stiftungsrat sitzen"}, {"kategorie": "", "text": "Der Stiftungsrat besteht üblicherweise aus mehreren Personen, die gemeinsam die Kontrollfunktion wahrnehmen und den Stiftungsvorstand in seiner Arbeit unterstützen und überwachen"}, {"kategorie": "", "text": "Der Stiftungsrat hat weitreichende Informations- und Einsichtsrechte, um seine Aufsichtspflichten erfüllen zu können. Mitglieder des Stiftungsrats sind zur Sorgfalt verpflichtet und haften bei grober Fahrlässigkeit oder Pflichtverletzung."}]'::jsonb, ''),
  ('stftungsuakundn', 'Stftungsuakundn', '', '', '', '', 'Stiftungsurkunde', '[{"kategorie": "allg.", "text": "\"zentrales Gründungsdokument einer [[Stiftung]], das deren grundlegende Struktur, Ziele und Regelungen festlegt\""}, {"kategorie": "", "text": "Die Stiftungsurkunde wird vom Stifter erstellt und ist rechtlich bindend. In Österreich regelt die Stiftungsurkunde wichtige Bestimmungen zur Organisation, Verwaltung und Verwendung des Stiftungsvermögens und bildet somit die Grundlage für die Tätigkeit der Stiftung und die Arbeit des [[Stiftungsvorstands]]"}, {"kategorie": "", "text": "Inhalte einer Stiftungsurkunde:  (i) Stiftungszweck: Der Zweck der Stiftung wird in der Urkunde genau definiert. Dies kann ein gemeinnütziger, privater oder wohltätiger Zweck sein, wie die Förderung von Wissenschaft, Kunst, Bildung oder die langfristige Verwaltung eines Familienvermögens;  (ii)  Stiftungsvermögen: Die Stiftungsurkunde enthält Informationen über das eingebrachte Vermögen und legt fest, wie dieses verwaltet und verwendet werden soll, um den Stiftungszweck zu erfüllen;  (iii) Organisation der Stiftung: Die Urkunde bestimmt die Struktur der Stiftung und legt fest, welche Organe (z. B. [[Stiftungsvorstand]], gegebenenfalls [[Stiftungsrat]]) für die Leitung und Kontrolle zuständig sind und wie diese bestellt werden;  (iv) Begünstigte: Die Stiftungsurkunde kann Begünstigte festlegen, also Personen oder Institutionen, die durch die Stiftung unterstützt werden. Hierbei wird auch festgelegt, wie und in welchem Umfang die Begünstigten Leistungen erhalten;  (v) Regelungen zur Änderung und Auflösung: Die Urkunde enthält Bestimmungen, unter welchen Umständen der Stiftungszweck oder die Stiftungsstruktur geändert oder die Stiftung aufgelöst werden kann, falls dies notwendig wird;  (vi) \nAufgaben und Pflichten des [[Stiftungsvorstands]]: Die Aufgaben und Verantwortlichkeiten des Stiftungsvorstands werden in der Stiftungsurkunde festgelegt, ebenso wie die Berichtspflichten und Kontrollmechanismen"}, {"kategorie": "", "text": "Die Stiftungsurkunde ist rechtlich bindend und gibt den Rahmen für alle Handlungen der [[Stiftung]] vor. Sie sichert die Erfüllung des Stifterwillens und schützt das Stiftungsvermögen vor zweckfremder Verwendung. Änderungen an der Stiftungsurkunde sind nur in streng geregelten Fällen möglich und unterliegen oft einer behördlichen Genehmigung"}, {"kategorie": "", "text": "Die Stiftungsurkunde bildet somit das Fundament der Stiftung und gewährleistet die dauerhafte Erfüllung des Stiftungszwecks im Sinne des Stifters."}]'::jsonb, ''),
  ('gsoeschoftsvatrog', 'Gsöschoftsvatrog', '', '', '', '', 'Gesellschaftsvertrag', '[{"kategorie": "allg.", "text": "\"theoretische und rechtliche Grundlage, welche die Bildung und Organisation einer Gesellschaft beschreibt\""}, {"kategorie": "", "text": "Der Begriff stammt ursprünglich aus der Philosophie und wird heute auch in der Rechtswissenschaft verwendet"}, {"kategorie": "", "text": "In der Philosophie bezieht sich der Gesellschaftsvertrag auf ein Konzept, das von Denkern wie Thomas Hobbes, John Locke und Jean-Jacques Rousseau geprägt wurde. Sie beschrieben den Gesellschaftsvertrag als eine hypothetische Vereinbarung zwischen Individuen, die sich freiwillig aus ihrem ursprünglichen Naturzustand heraus begeben und einer Gemeinschaft oder einem Staat unterordnen, um Frieden, Sicherheit und Rechte zu gewährleisten. Durch den Gesellschaftsvertrag verzichten die Menschen auf bestimmte Freiheiten zugunsten eines geordneten Zusammenlebens und gemeinsamer Regeln, die durch eine Autorität oder Regierung geschützt werden"}, {"kategorie": "", "text": "Juristische Definition: In der Rechtswissenschaft bezieht sich der Gesellschaftsvertrag auf das Gründungsdokument, das die Struktur, Rechte und Pflichten einer Gesellschaft (z.B. einer [[GmbH]] oder einer [[Personengesellschaft]]) festlegt"}, {"kategorie": "", "text": "Der Gesellschaftsvertrag regelt unter anderem:  (i) die Rechtsform der Gesellschaft,  (ii) die Aufgaben und Befugnisse der Gesellschafter,  (iii) den Geschäftszweck,  (iv) die Verteilung von Gewinn und Verlust,  (v) die Haftung der Gesellschafter,  sowie (vi) die Regeln für die Auflösung der Gesellschaft"}, {"kategorie": "", "text": "Der Gesellschaftsvertrag ist in der Regel notariell beurkundet und bildet die rechtliche Grundlage für die Existenz und Funktionsweise der Gesellschaft."}]'::jsonb, ''),
  ('satzung', 'Satzung', '', '', '', '', 'Satzung', '[{"kategorie": "allg.", "text": "\"verbindliche schriftliche Regelung, welche die internen Angelegenheiten und das organisatorische Grundgerüst einer [[juristischen]] Person oder Organisation festlegt\""}, {"kategorie": "", "text": "Satzungen kommen in verschiedenen Bereichen vor und regeln wesentliche Aspekte des Zusammenlebens, der Verwaltung und der Entscheidungsfindung"}, {"kategorie": "", "text": "Verwendung und Beispiele für Satzungen:  (i) [[Vereinsrecht]]: Bei Vereinen dient die Satzung als grundlegendes Regelwerk und legt z. B. den Zweck des Vereins, die Mitgliedschaftsbedingungen, die Rechte und Pflichten der Mitglieder, die Zusammensetzung des Vorstands und das Verfahren für Beschlüsse fest. Jeder eingetragene Verein (e.V.) ist verpflichtet, eine Satzung zu haben, die im [[Vereinsregister]] hinterlegt wird;  (ii) [[Gesellschaftsrecht]]: Bei [[Kapitalgesellschaften]], wie [[Aktiengesellschaften]] (AG) oder [[Genossenschaften]], wird die Satzung häufig als [[Gesellschaftsvertrag]] bezeichnet und enthält zentrale Bestimmungen zur Organisation, etwa zur Verteilung von Gewinnen, zur Aufgabenverteilung in Organen (z. B. [[Aufsichtsrat]], [[Vorstand]]) und zum Stimmrecht;  (iii) [[Öffentliches]] Recht: Auch Kommunen und andere öffentlich-rechtliche [[Körperschaften]] geben sich Satzungen, z. B. für Abgabenordnungen, Gebührenregelungen oder Verhaltensrichtlinien. Diese Satzungen sind bindend und gelten als rechtliche Normen, die für alle Mitglieder oder Bewohner im jeweiligen Geltungsbereich verbindlich sind"}, {"kategorie": "", "text": "Eine Satzung enthält in der Regel Bestimmungen über:  (i) den Zweck und das Ziel der Organisation,  (ii) den Aufbau und die Organisation der Führung (z. B. Vorstand),  (iii) die Rechte und Pflichten der Mitglieder,  (iv) die Regeln für die Beschlussfassung,  (v) die Verwaltung von Finanzen,  (vi) die Voraussetzungen und das Verfahren für die Änderung der Satzung"}, {"kategorie": "", "text": "Die Satzung ist eine rechtlich bindende Grundlage und muss daher klar und eindeutig formuliert sein. Sie schafft Transparenz, regelt Konfliktpotenziale und fördert die rechtliche Sicherheit innerhalb der Organisation."}]'::jsonb, ''),
  ('vareinsregista', 'Vareinsregista', '', '', '', '', 'Vereinsregister', '[{"kategorie": "allg.", "text": "\"öffentlich geführtes Verzeichnis, in dem alle rechtlich anerkannten Vereine eines Landes eingetragen sind\""}, {"kategorie": "", "text": "Es dient dazu, die Existenz und wesentliche Informationen über einen Verein rechtlich nachvollziehbar und transparent zu machen"}, {"kategorie": "", "text": "In Österreich wird das Vereinsregister von den zuständigen Vereinsbehörden ([[Bezirkshauptmannschaften]] oder [[Magistrate]]) geführt"}, {"kategorie": "", "text": "Das Vereinsregister soll die Rechtssicherheit und Transparenz über die Existenz und die wesentlichen Strukturen der [[Vereine]] gewährleisten. Es ermöglicht Behörden, Mitgliedern und der Öffentlichkeit, grundlegende Informationen über einen Verein zu erhalten, wie zum Beispiel den Vereinszweck, die [[Satzung]] und die Namen der vertretungsbefugten Personen (z. B. [[Vorstand]])"}, {"kategorie": "", "text": "In das Vereinsregister werden unter anderem folgende Informationen aufgenommen:  (i) Vereinsname und Sitz des Vereins,  (ii) Zweck des Vereins,  (iii) Satzung des Vereins,  (iv) Vertretungsbefugte Personen ([[Vorstand]]),  (v) Datum der Eintragung und gegebenenfalls der Auflösung,  (vi) Änderungen in der Satzung oder im Vorstand"}, {"kategorie": "", "text": "Das Vereinsregister ist in Österreich öffentlich einsehbar, und Auszüge daraus können bei der zuständigen Behörde angefordert werden"}, {"kategorie": "", "text": "Jede Änderung, z. B. ein Wechsel im Vorstand oder eine Satzungsänderung, muss dem Vereinsregister gemeldet und dort aktualisiert werden, um die fortlaufende Transparenz zu gewährleisten."}]'::jsonb, ''),
  ('schdatut', 'Schdatut', '', '', '', '', 'Statut', '[{"kategorie": "allg.", "text": "\"Regelwerk, das die grundlegenden Vorschriften und Bestimmungen für das Funktionieren einer Organisation, Institution, [[Körperschaft]] oder eines [[Vereins]] festlegt\""}, {"kategorie": "", "text": "Es dient als rechtliche Grundlage und gibt den Rahmen für die interne Struktur und die Abläufe innerhalb der Organisation vor"}, {"kategorie": "", "text": "Der Begriff wird häufig synonym mit [[Satzung]] verwendet, insbesondere in Österreich, wo „Statut“ oft die grundlegende Rechtsordnung eines Vereins oder einer Institution bezeichnet"}, {"kategorie": "", "text": "Ein Statut enthält in der Regel:  (i) den Zweck und die Ziele der Organisation,  (ii) die Organisationsstruktur und die Kompetenzen der verschiedenen Organe (z. B. [[Vorstand]], Mitgliederversammlung),  (iii) die Rechte und Pflichten der Mitglieder,  (iv) Regelungen zu [[Wahlen]] und Beschlussfassungen,  (iv) Bestimmungen zur Finanzverwaltung,  (v) das Verfahren für Änderungen am Statut,\ngegebenenfalls das Verfahren zur Auflösung der Organisation"}, {"kategorie": "", "text": "Vereine und Organisationen: Ein Statut dient als rechtliche Grundlage und ist im [[Vereinsrecht]] vieler Länder, darunter Österreich, verpflichtend. Es definiert die internen Abläufe und sichert Transparenz"}, {"kategorie": "", "text": "[[Körperschaften]] und [[Stiftungen]]: Auch [[Körperschaften]] des öffentlichen Rechts und Stiftungen arbeiten auf Basis von Statuten, die ihre Verwaltungsstruktur und Entscheidungsprozesse regeln"}, {"kategorie": "", "text": "Unternehmen und öffentliche Institutionen: In manchen Ländern, insbesondere in Österreich und der Schweiz, werden auch Unternehmensgrundlagen und Regelwerke öffentlicher Institutionen als „Statuten“ bezeichnet"}, {"kategorie": "", "text": "Unterschied zur Satzung: Obwohl „Statut“ und „Satzung“ oft synonym verwendet werden, bezeichnet das Statut häufig eine verbindliche Grundordnung, die nicht nur auf Vereine beschränkt ist, sondern auch für andere Körperschaften und Institutionen gilt."}]'::jsonb, ''),
  ('gmbh', 'GmbH', '', '', '', '', 'GmbH', '[{"kategorie": "", "text": "Das bedeutet, dass die Gesellschafter im Falle von Verbindlichkeiten des Unternehmens grundsätzlich nur mit dem eingebrachten Gesellschaftskapital und nicht mit ihrem privaten Vermögen haften"}, {"kategorie": "", "text": "Diese Rechtsform ist besonders bei kleinen und mittleren Unternehmen beliebt, da sie eine klare Trennung zwischen Unternehmens- und Privatvermögen bietet und gleichzeitig die Haftung begrenzt"}, {"kategorie": "", "text": "Merkmale einer GmbH:  (i) Beschränkte Haftung: Die Gesellschafter haften nicht persönlich, sondern nur mit ihrer [[Kapitaleinlage]]. Das Mindeststammkapital beträgt in Deutschland beispielsweise 25.000 Euro und in Österreich 35.000 Euro, wobei nur ein Teil davon bei der Gründung eingezahlt werden muss;  (ii) [[Gesellschaftsvertrag]]: Die GmbH wird durch einen Gesellschaftsvertrag (auch [[Satzung]] genannt) gegründet, der notariell beurkundet wird. Dieser Vertrag legt u.a. den Unternehmenszweck, die Höhe des [[Stammkapitals]], die Verteilung der Anteile und die Regelungen zur Gewinnverteilung fest;  (iii) [[Geschäftsführung]]: Die GmbH hat eine oder mehrere Personen als [[Geschäftsführer]], die für das Tagesgeschäft und die Umsetzung der Unternehmensziele verantwortlich sind;  (iv) Die [[Gesellschafterversammlung]] ist das oberste Organ der GmbH und entscheidet über grundlegende Angelegenheiten;  (v) Gewinnverteilung: Gewinne werden entsprechend den Anteilen der [[Gesellschafter]] verteilt, sofern der Gesellschaftsvertrag nichts anderes festlegt;  (vi) Publizitätspflichten: GmbHs unterliegen bestimmten gesetzlichen Offenlegungspflichten, wie etwa der jährlichen Veröffentlichung des [[Jahresabschlusses]] im [[Handelsregister]]"}, {"kategorie": "", "text": "Eine GmbH entsteht rechtlich erst mit der Eintragung ins Handelsregister. Dafür müssen das Mindestkapital nachgewiesen und der Gesellschaftsvertrag erstellt sein. Diese Eintragung macht die GmbH zu einer eigenständigen juristischen Person, die Verträge abschließen und vor Gericht klagen oder verklagt werden kann."}]'::jsonb, ''),
  ('haundlsregista', 'Haundlsregista', '', '', '', '', 'Handelsregister', '[{"kategorie": "allg.", "text": "\"öffentliches Verzeichnis, in dem alle relevanten Informationen über die kaufmännischen Unternehmen eines Landes festgehalten werden\""}, {"kategorie": "", "text": "Es dient zur rechtlichen und wirtschaftlichen Transparenz und ermöglicht es Dritten, grundlegende Informationen über Unternehmen einzusehen, wie z. B. deren [[Rechtsform]], Sitz, Geschäftszweck, [[Geschäftsführer]] und Haftungsverhältnisse"}, {"kategorie": "", "text": "Das Handelsregister stellt sicher, dass wesentliche Informationen über Unternehmen öffentlich zugänglich sind, um Rechts- und Vertragssicherheit im Geschäftsverkehr zu gewährleisten. Es ermöglicht potenziellen Geschäftspartnern, Gläubigern und Kunden, sich über die Struktur, Vertretungsbefugnis und finanzielle Lage von Unternehmen zu informieren"}, {"kategorie": "", "text": "Im Handelsregister werden verschiedene Angaben zu einem Unternehmen vermerkt, darunter:  (i) Name und Sitz des Unternehmens,  (ii) Rechtsform (z. B. [[GmbH]], [[AG]]),   (iii) Geschäftszweck des Unternehmens,  (iv) Vertretungsberechtigte Personen (z. B. [[Geschäftsführer]], [[Vorstände]]),  (v) [[Stammkapital]] oder [[Grundkapital]] (bei GmbH und AG),  (v) Eintragungen über Insolvenzen oder Liquidationen,\nÄnderungen im Unternehmen, z. B. Geschäftsführerwechsel, Kapitalerhöhungen, Fusionen;  (vi) Organisation und Einsicht: In Österreich wird das Handelsregister vom zuständigen Firmenbuchgericht geführt. Die Einträge werden öffentlich zugänglich gemacht, und die Einsicht ist mittlerweile auch online möglich"}, {"kategorie": "", "text": "Der Eintrag ins Handelsregister macht ein Unternehmen offiziell als Kaufmann bzw. juristische Person bekannt und erlaubt ihm, am Wirtschaftsverkehr teilzunehmen"}, {"kategorie": "", "text": "Bestimmte Informationen müssen regelmäßig veröffentlicht werden, um Transparenz und Sicherheit im Geschäftsverkehr zu schaffen"}, {"kategorie": "", "text": "Kapitalgesellschaften wie die GmbH und AG entstehen erst mit der Eintragung ins Handelsregister und erhalten damit den Status als [[juristische]] Person."}]'::jsonb, ''),
  ('gsoeschoftavasaummlung', 'Gsöschoftavasaummlung', '', '', '', '', 'Gesellschafterversammlung', '[{"kategorie": "allg.", "text": "\"höchstes Entscheidungsgremium einer Gesellschaft, insbesondere bei [[Kapitalgesellschaften]] wie der [[GmbH]]\""}, {"kategorie": "", "text": "In der Gesellschafterversammlung treffen die [[Gesellschafter]] (Eigentümer bzw. Anteilseigner) wichtige Beschlüsse über die grundlegenden Angelegenheiten des Unternehmens"}, {"kategorie": "", "text": "Die Versammlung dient der Meinungsbildung und Entscheidungsfindung und gibt den Gesellschaftern die Möglichkeit, ihre Interessen und Rechte auszuüben"}, {"kategorie": "", "text": "Die Gesellschafterversammlung hat eine Reihe von wichtigen Aufgaben und Befugnissen, die typischerweise in der [[Satzung]] bzw. im [[Gesellschaftsvertrag]] der Gesellschaft oder gesetzlich festgelegt sind. Dazu gehören unter anderem:  (i)  Bestellung und Abberufung der [[Geschäftsführung]]: Die Gesellschafter entscheiden über die Auswahl und Abberufung der [[Geschäftsführer]];  (ii) Feststellung des [[Jahresabschlusses]] und Gewinnverwendung: Die Versammlung nimmt den Jahresabschluss zur Kenntnis und entscheidet über die Verwendung des Gewinns (z. B. Ausschüttung oder Rücklagenbildung);  (iii) Änderungen des Gesellschaftsvertrags: Änderungen in der Satzung oder im Gesellschaftsvertrag, wie etwa eine Kapitalerhöhung, bedürfen in der Regel der Zustimmung der Gesellschafter;  (iv) Entscheidungen über strategische Fragen: Größere Investitionen, Umstrukturierungen oder Änderungen im Geschäftsmodell werden oft in der Gesellschafterversammlung diskutiert und beschlossen;  (v) Liquidation und Auflösung: Die Entscheidung über die Liquidation oder Auflösung der Gesellschaft liegt in der Regel bei den Gesellschaftern"}, {"kategorie": "", "text": "Ablauf der Gesellschafterversammlung: Die Gesellschafterversammlung findet regelmäßig statt, häufig einmal im Jahr als ordentliche Versammlung, und wird von der Geschäftsführung einberufen"}, {"kategorie": "", "text": "Außerordentliche Gesellschafterversammlungen können bei besonderen Anlässen (z. B. Unternehmenskrisen oder wichtigen Entscheidungen) einberufen werden"}, {"kategorie": "", "text": "Die Beschlüsse werden durch Abstimmung gefasst, wobei das Stimmrecht der Gesellschafter in der Regel an ihre Kapitalanteile gekoppelt ist. Das Ergebnis wird im Protokoll festgehalten."}]'::jsonb, ''),
  ('generalvasaummlung', 'Generalvasaummlung', '', '', '', '', 'Generalversammlung', '[{"kategorie": "allg.", "text": "\"höchstes Entscheidungsorgan einer [[Aktiengesellschaft]] (AG), [[Genossenschaft]] oder eines [[Vereins]]\""}, {"kategorie": "", "text": "Sie stellt eine Versammlung aller Mitglieder bzw. Aktionäre dar und dient der Ausübung ihrer grundlegenden Mitbestimmungs- und Kontrollrechte"}, {"kategorie": "", "text": "In der Generalversammlung werden wichtige, häufig grundlegende Entscheidungen getroffen, welche die Zukunft der Gesellschaft betreffen"}, {"kategorie": "", "text": "Die Generalversammlung ist in der Regel zuständig für:  (i) Wahl des [[Vorstandes]] und [[Aufsichtsrates]]: Die Mitglieder wählen in der Generalversammlung die Führungsgremien, also in der Regel den Vorstand und den Aufsichtsrat (falls vorgesehen);  (ii) Entlastung des Vorstands und Aufsichtsrats: Die Generalversammlung entscheidet darüber, ob dem Vorstand und Aufsichtsrat für ihre Arbeit des abgelaufenen Geschäftsjahres Entlastung erteilt wird;  (iii) Genehmigung des [[Jahresabschlusses]] und Gewinnverwendung: Die Versammlung nimmt den Jahresabschluss entgegen und beschließt über die Verwendung des Gewinns, zum Beispiel die Auszahlung von [[Dividenden]] bei Aktiengesellschaften oder die Bildung von Rücklagen;  (iv) Beschluss über Satzungsänderungen: Die Generalversammlung kann Änderungen an der [[Satzung]] der Gesellschaft beschließen, z. B. die Anpassung des Geschäftszwecks oder des Firmennamens;  (v) Grundlegende Unternehmensentscheidungen: Entscheidungen über Fusionen, Kapitalerhöhungen oder Auflösungen müssen in der Generalversammlung beschlossen werden"}, {"kategorie": "", "text": "Die Generalversammlung findet in der Regel jährlich statt, bei Aktiengesellschaften meist als ordentliche Hauptversammlung bezeichnet"}, {"kategorie": "", "text": "Die Einberufung erfolgt durch den [[Vorstand]] oder - in bestimmten Fällen - auch durch den [[Aufsichtsrat]] der Gesellschaft"}, {"kategorie": "", "text": "Jedes Mitglied bzw. jeder [[Aktionär]] ist - je nach Anzahl der gehaltenen Anteile - berechtigt, an der Generalversammlung teilzunehmen und dort sein Stimmrecht auszuüben"}, {"kategorie": "", "text": "Die Beschlüsse werden in der Generalversammlung durch Abstimmungen gefasst und in einem Protokoll dokumentiert"}, {"kategorie": "", "text": "Arten der Generalversammlung:  (i) [[Ordentliche]] Generalversammlung: Findet regelmäßig, meist jährlich, statt und behandelt die routinemäßigen Themen wie Jahresabschluss, Entlastung der Organe und Wahl der Führungsgremien;  (ii) [[Außerordentliche]] Generalversammlung: Wird einberufen, wenn außergewöhnliche Ereignisse oder Entscheidungen, wie [[Fusionen]] oder dringende strategische Änderungen, einer sofortigen Abstimmung bedürfen."}]'::jsonb, ''),
  ('hauptvasaummlung', 'Hauptvasaummlung', '', '', '', '', 'Hauptversammlung', '[{"kategorie": "allg.", "text": "\"höchstes Entscheidungsgremium einer [[Aktiengesellschaft]] (AG)\""}, {"kategorie": "", "text": "Sie stellt eine Versammlung aller [[Aktionäre]] dar und dient dazu, über wesentliche Angelegenheiten der Gesellschaft zu entscheiden und die Interessen der Aktionäre wahrzunehmen"}, {"kategorie": "", "text": "Die Hauptversammlung ermöglicht den Aktionären, grundlegende Mitbestimmungs- und Kontrollrechte auszuüben und sich über den Stand und die Entwicklung des Unternehmens zu informieren"}, {"kategorie": "", "text": "Die Hauptversammlung hat eine Reihe von wichtigen Aufgaben und Befugnissen, die gesetzlich und in der [[Satzung]] der Gesellschaft festgelegt sind. Zu den typischen Aufgaben gehören:  (i) [[Entlastung]] von [[Vorstand]] und [[Aufsichtsrat]]: Die Aktionäre entscheiden darüber, ob sie dem Vorstand und dem Aufsichtsrat für ihre Arbeit im abgelaufenen Geschäftsjahr Entlastung erteilen;  (ii) Verwendung des [[Bilanzgewinns]]: Die Hauptversammlung entscheidet über die Verteilung des Gewinns, insbesondere über die Auszahlung von [[Dividenden]] an die Aktionäre;  (iii) Wahl der Aufsichtsratsmitglieder: Die Hauptversammlung wählt die Mitglieder des Aufsichtsrats, sofern diese nicht durch Arbeitnehmervertreter besetzt werden;  (iv) Wahl des [[Abschlussprüfers]]: Der Prüfer, der den [[Jahresabschluss]] kontrolliert, wird von der Hauptversammlung bestellt;  (v) Satzungsänderungen: Grundlegende Änderungen der [[Satzung]] bzw. des [[Gesellschaftsvertrags]], wie z. B. eine Änderung des Unternehmenszwecks oder des Firmennamens, bedürfen der Zustimmung der Hauptversammlung;  (vi) Kapitalmaßnahmen: Die Hauptversammlung entscheidet über [[Kapitalerhöhungen]] oder -herabsetzungen sowie die Ausgabe neuer Aktien;  (vii) Grundlegende Unternehmensentscheidungen: Auch bei [[Fusionen]], [[Übernahmen]] oder der [[Liquidation]] der Gesellschaft ist die Zustimmung der Hauptversammlung erforderlich"}, {"kategorie": "", "text": "Die Hauptversammlung wird in der Regel einmal jährlich vom Vorstand einberufen und wird dann als [[Ordentliche Hauptversammlung]] bezeichnet"}, {"kategorie": "", "text": "Eine [[Außerordentliche]] Hauptversammlung kann zusätzlich einberufen werden, wenn dringende Entscheidungen erforderlich sind"}, {"kategorie": "", "text": "Die Einberufung erfolgt unter Einhaltung einer gesetzlich vorgeschriebenen Frist und muss eine [[Tagesordnung]] enthalten, die die zu behandelnden Themen klar auflistet"}, {"kategorie": "", "text": "Jeder Aktionär ist zur Teilnahme berechtigt und kann sein Stimmrecht entweder persönlich oder durch einen Bevollmächtigten ausüben. Das Stimmrecht ist in der Regel an die Anzahl der Aktien gebunden (eine Aktie – eine Stimme)"}, {"kategorie": "", "text": "Die Abstimmungen erfolgen über die auf der Tagesordnung stehenden Punkte, und die Ergebnisse werden in einem Protokoll festgehalten."}]'::jsonb, ''),
  ('mediin', 'Mediin', '', '', '', '', 'Medien', '[{"kategorie": "allg.", "text": "\"sämtliche Kommunikationsmittel und Plattformen, die Informationen, Nachrichten, Meinungen und Unterhaltung verbreiten\""}, {"kategorie": "", "text": "Dazu gehören traditionelle Medien wie [[Printmedien]] (Zeitungen, Zeitschriften), [[Rundfunk]] (Radio, Fernsehen) sowie [[digitale]] Medien (Online-Nachrichtenportale, soziale Netzwerke)\""}, {"kategorie": "", "text": "Die österreichische Medienlandschaft spielt eine zentrale Rolle in der [[öffentlichen]] Meinungsbildung und der politischen Kommunikation"}, {"kategorie": "", "text": "Österreich verfügt über eine breite Palette an Medienangeboten, von nationalen Tageszeitungen und Wochenzeitschriften bis hin zu regionalen und lokalen Medien"}, {"kategorie": "", "text": "Es gibt sowohl private als auch öffentliche Rundfunkanstalten. Der [[ORF]] ([[Österreichischer]] Rundfunk), der größte öffentlich-rechtliche Sender, spielt eine führende Rolle im Radio- und Fernsehbereich"}, {"kategorie": "", "text": "Neben dem öffentlich-rechtlichen ORF gibt es zahlreiche private Fernseh- und Radiosender, die sich durch Werbung und kommerzielle Einnahmen finanzieren"}, {"kategorie": "", "text": "Auch der Printsektor ist stark privatwirtschaftlich geprägt, mit großen Zeitungen wie der [[Kronen]] Zeitung, dem [[Standard]], der [[Presse]] und dem [[Kurier]]"}, {"kategorie": "", "text": "In den letzten Jahren haben digitale Medien in Österreich stark an Bedeutung gewonnen. Online-Nachrichtenportale und soziale Medien sind wichtige Plattformen für die Verbreitung von Informationen und politischen Diskussionen geworden. Viele traditionelle Medien haben sich durch Online-Portale und Apps an den digitalen Wandel angepasst, um eine breitere Leserschaft zu erreichen"}, {"kategorie": "", "text": "In Österreich ist die [[Pressefreiheit]] durch die [[Verfassung]] geschützt. Die Medien sind grundsätzlich unabhängig und dürfen frei berichten, jedoch gibt es rechtliche Rahmenbedingungen, wie das Mediengesetz und das Rundfunkgesetz, die die journalistischen Standards regeln"}, {"kategorie": "", "text": "Die Kommunikationsbehörde Austria (KommAustria) überwacht die Einhaltung dieser Gesetze und stellt sicher, dass journalistische Sorgfaltspflichten eingehalten werden, insbesondere im Rundfunkbereich"}, {"kategorie": "", "text": "In Österreich gibt es eine gewisse Konzentration im Mediensektor, da einige wenige Verlagsgruppen einen Großteil der Printmedien und digitalen Plattformen besitzen. Diese Konzentration wirft Fragen zur Medienvielfalt und Unabhängigkeit auf, da die Meinungsbildung potenziell von wenigen Akteuren dominiert werden könnte."}]'::jsonb, ''),
  ('nichtigkeitsbeschweade', 'Nichtigkeitsbeschweade', '', '', '', '', 'Nichtigkeitsbeschwerde', '[{"kategorie": "jur.", "text": "\"[[Rechtsmittel]] im österreichischen Strafrecht, das zur Anfechtung eines Urteils dient, wenn schwerwiegende Rechtsfehler im Verfahren oder in der Urteilsfindung vorliegen\""}, {"kategorie": "", "text": "Sie wird in der Regel beim [[Obersten]] Gerichtshof (OGH) eingelegt und ist ein wesentliches Instrument zur Sicherstellung der [[Rechtsstaatlichkeit]] im Strafprozess"}, {"kategorie": "", "text": "Die Nichtigkeitsbeschwerde konzentriert sich auf spezifische Verfahrensmängel oder Rechtsanwendungsfehler und dient nicht der Überprüfung der Tatsachenfeststellung oder der Beweiswürdigung"}, {"kategorie": "", "text": "Die Nichtigkeitsbeschwerde kann nur gegen erstinstanzliche Urteile eines [[Geschworenengerichts]] oder [[Schöffengerichts]] erhoben werden"}, {"kategorie": "", "text": "Die Nichtigkeitsbeschwerde kann auf eine Reihe von Gründen gestützt werden, die in der [[Strafprozessordnung]] (StPO) klar definiert sind. Zu den typischen Nichtigkeitsgründen gehören: (i) fehlerhafte Anklage oder unzuständiges Gericht,  (ii) Verletzung von Verteidigungsrechten oder Rechtsverletzungen während der Hauptverhandlung,  (iii) fehlerhafte Beweisaufnahme oder Beweisausschluss,  (iv) fehlerhafte Zusammensetzung des Gerichts,  (v) falsche Anwendung des materiellen Strafrechts, sowie  (vi) unzureichende oder fehlerhafte Urteilsbegründung"}, {"kategorie": "", "text": "Der [[Oberste]] Gerichtshof prüft, ob einer der in der [[Strafprozessordnung]] vorgesehenen Nichtigkeitsgründe vorliegt. Wenn die Nichtigkeitsbeschwerde erfolgreich ist, kann der OGH das Urteil aufheben und den Fall zur Neuverhandlung an das erstinstanzliche Gericht zurückverweisen oder in Ausnahmefällen selbst ein neues Urteil fällen. Wenn die Beschwerde abgelehnt wird, bleibt das ursprüngliche Urteil bestehen"}, {"kategorie": "", "text": "Die Nichtigkeitsbeschwerde unterscheidet sich von der [[Berufung]] und der [[Revision]] dadurch, dass sie sich ausschließlich auf Rechtsfehler und Verfahrensmängel konzentriert, die zur Nichtigkeit des Verfahrens führen können.\nEine Berufung bezieht sich hingegen oft auf das Strafmaß, während die Revision im Zivilrecht Rechtsfragen prüft"}, {"kategorie": "", "text": "Die Nichtigkeitsbeschwerde kann sowohl vom Angeklagten als auch von der Staatsanwaltschaft eingebracht werden, wenn sie der Meinung sind, dass das Verfahren fehlerhaft war oder das Gericht das Recht falsch angewendet hat."}]'::jsonb, ''),
  ('zivueueprozessoadnung', 'Zivüüprozessoadnung', '', '', '', '', 'Zivilprozessordnung', '[{"kategorie": "", "text": "Die Zivilprozessordnung stellt sicher, dass zivilrechtliche Streitigkeiten, etwa über Vertragsangelegenheiten, Eigentumsrechte, Schadenersatzansprüche oder Familienrecht, unter Einhaltung klarer Verfahrensvorschriften gelöst werden"}, {"kategorie": "", "text": "Sie garantiert ein faires Verfahren für alle Beteiligten und stützt sich auf die Prinzipien der [[Rechtsstaatlichkeit]] und Gerechtigkeit\""}, {"kategorie": "", "text": "Die ZPO beschreibt die einzelnen Phasen eines Zivilverfahrens:  (i) Klageeinbringung (der Kläger reicht die Klage beim zuständigen Gericht ein, in welcher er seine Ansprüche darlegt);  (ii) Vorbereitung der Verhandlung (beide Parteien tauschen Schriftsätze aus, in denen sie ihre Positionen und Beweismittel vorlegen);  (iii) Hauptverhandlung (vor Gericht wird der Streitgegenstand erörtert, Beweise werden vorgelegt, und Zeugen werden vernommen);  (iv) Urteil (das Gericht entscheidet über den Fall und erlässt ein Urteil, das die Ansprüche klärt und ggf. Rechtsfolgen, wie etwa Schadenersatz, festlegt)"}, {"kategorie": "", "text": "Die ZPO sieht verschiedene Rechtsmittel vor, um gegen Urteile der ersten Instanz vorzugehen: (i)\n[[Berufung]] (ein Rechtsmittel gegen erstinstanzliche Urteile, bei dem sowohl die Tatsachenfeststellung als auch die Rechtsanwendung überprüft werden),  (ii) [[Revision]] (ein Rechtsmittel gegen Urteile höherer Instanzen, das sich ausschließlich auf Rechtsfragen konzentriert und vor dem [[Obersten]] Gerichtshof verhandelt wird),  (iii) [[Rekurs]] (ein Rechtsmittel gegen Beschlüsse des Gerichts, z. B. Entscheidungen über Verfahrensfragen oder [[Zwangsvollstreckungen]])."}]'::jsonb, ''),
  ('schdrofprozessoadnung', 'Schdrofprozessoadnung', '', '', '', '', 'Strafprozessordnung', '[{"kategorie": "", "text": "Sie regelt die Rechte und Pflichten von Ermittlungsbehörden, Staatsanwaltschaft, Angeklagten, Verteidigern und Gerichten sowie den gesamten Ablauf eines Strafverfahrens – von den Ermittlungen bis zur gerichtlichen Entscheidung\""}, {"kategorie": "", "text": "Durch die StPO wird sichergestellt, dass Strafprozesse in Österreich in Übereinstimmung mit den Prinzipien der [[Rechtsstaatlichkeit]], Gerechtigkeit und dem Schutz der [[Grundrechte]] durchgeführt werden"}, {"kategorie": "", "text": "Die Strafprozessordnung legt fest, wie ein Strafverfahren strukturiert ist und welche Phasen es durchläuft:  (i) Ermittlungsverfahren (nach Bekanntwerden einer Straftat beginnt die [[Staatsanwaltschaft]] das Ermittlungsverfahren. Es wird ermittelt, ob genügend Beweise für eine Anklage vorliegen. Die Polizei führt die Ermittlungen unter Aufsicht der Staatsanwaltschaft durch);  (ii) Anklage (wenn genügend Beweise vorliegen, erhebt die Staatsanwaltschaft Anklage, und es wird ein Hauptverfahren vor Gericht eingeleitet);  (iii) Hauptverfahren (in der Hauptverhandlung vor Gericht wird die Schuld des Angeklagten festgestellt. Beweise werden präsentiert, und der Angeklagte hat das Recht auf Verteidigung);  (iv) Urteil: Das Gericht entscheidet am Ende des Hauptverfahrens über die Schuld des Angeklagten und verhängt, falls nötig, eine Strafe);  (v) Rechtsmittelverfahren (nach dem Urteil können Rechtsmittel, wie etwa [[Berufung]] oder [[Nichtigkeitsbeschwerde]], eingelegt werden)."}]'::jsonb, ''),
  ('schoeffngricht', 'Schöffngricht', '', '', '', '', 'Schöffengericht', '[{"kategorie": "jur.", "text": "\"besondere  Form des Strafgerichts, bei dem sowohl Berufsrichter als auch Laienrichter, die sogenannten [[Schöffen]], gemeinsam über die Schuldfrage und das Strafmaß entscheiden\""}, {"kategorie": "", "text": "Das Schöffengericht wird bei mittelschweren Straftaten eingesetzt und kombiniert die Fachkenntnisse der Berufsrichter mit der Perspektive von Laien aus der Bevölkerung, um eine gerechte Urteilsfindung zu gewährleisten"}, {"kategorie": "", "text": "Ein Schöffengericht besteht aus zwei Schöffen (Laienrichter) und einem oder zwei Berufsrichtern, je nach Schwere des Falles. Die Schöffen werden aus der Bevölkerung ausgewählt und haben keine juristische Ausbildung. Sie sind ehrenamtlich tätig und entscheiden gemeinsam mit den Berufsrichtern sowohl über die Schuldfrage als auch über das Strafmaß"}, {"kategorie": "", "text": "Das Schöffengericht ist zuständig für Straftaten mittleren Schweregrads, bei denen die Strafandrohung bei mindestens fünf Jahren Freiheitsstrafe, aber nicht über 10 Jahre Freiheitsstrafe liegt. Typische Delikte, die vor einem Schöffengericht verhandelt werden, sind beispielsweise schwere Körperverletzung, Raub oder Betrug"}, {"kategorie": "", "text": "Gegen Urteile des Schöffengerichts können der Angeklagte oder die [[Staatsanwaltschaft]] eine Berufung gegen das Strafmaß oder eine [[Nichtigkeitsbeschwerde]] wegen Rechtsfehlern einbringen"}, {"kategorie": "", "text": "Die Rechtsmittel gehen dann an ein höheres Gericht ([[Oberlandesgericht]], [[Oberster]] Gerichtshof), das die Entscheidung des Schöffengerichts überprüft."}]'::jsonb, ''),
  ('geschwoaranangricht', 'Geschwoaranangricht', '', '', '', '', 'Geschworenengericht', '[{"kategorie": "jur.", "text": "\"besondere Form des [[Strafgerichts]], bei dem Laien, die sogenannten [[Geschworenen]], gemeinsam mit Berufsrichtern über die Schuldfrage eines Angeklagten in schweren Strafsachen entscheiden\""}, {"kategorie": "", "text": "Das Geschworenengericht wird in Fällen eingesetzt, in denen das [[Strafgesetz]] besonders schwere Delikte vorsieht, beispielsweise bei Mord, Totschlag oder Hochverrat"}, {"kategorie": "", "text": "Es ist Teil des österreichischen Strafgerichtssystems und trägt zur Einbindung von Bürgern in die Rechtsprechung bei"}, {"kategorie": "", "text": "Ein Geschworenengericht besteht aus drei Berufsrichtern (darunter der Vorsitzende) und acht Geschworenen (Laienrichter), die per Zufall aus der Bevölkerung ausgewählt werden"}, {"kategorie": "", "text": "Die Geschworenen sind Laien, die keine juristische Ausbildung haben, und sie entscheiden ausschließlich über die Schuldfrage"}, {"kategorie": "", "text": "Die Berufsrichter entscheiden zusammen mit den Geschworenen über das Strafmaß, falls der Angeklagte schuldig gesprochen wird"}, {"kategorie": "", "text": "Das Geschworenengericht ist für besonders schwere Straftaten zuständig, bei denen das Strafgesetz eine Mindeststrafe von fünf Jahren Freiheitsentzug vorsieht. Dazu zählen Delikte wie Mord (§ 75 StGB), Totschlag (§ 76 StGB), Hochverrat (§ 242 StGB), Landesverrat (§ 252 StGB) und andere schwere Verbrechen"}, {"kategorie": "", "text": "Gegen Urteile eines Geschworenengerichts kann eine [[Nichtigkeitsbeschwerde]] sowie eine [[Berufung]] (gegen das Strafmaß) eingelegt werden. Die Nichtigkeitsbeschwerde kann sich auf Verfahrensfehler, Rechtsanwendungsfehler oder andere schwerwiegende Fehler im Verfahren beziehen. Die Überprüfung erfolgt durch den [[Obersten]] Gerichtshof (OGH)."}]'::jsonb, ''),
  ('schdrofausschbruch', 'Schdrofausschbruch', '', '', '', '', 'Strafausspruch', '[{"kategorie": "jur.", "text": "\"Teil eines [[Strafurteils]], in dem das [[Gericht]] nach einem [[Schuldspruch]] die konkrete [[Strafe]] festlegt, die der verurteilte [[Angeklagte]] zu tragen hat\""}, {"kategorie": "", "text": "Hierbei wird bestimmt, welche Art von Strafe (z. B. [[Geldstrafe]], [[Freiheitsstrafe]]) und in welchem Umfang sie verhängt wird"}, {"kategorie": "", "text": "Der Strafausspruch folgt auf die Feststellung der [[Schuld]] und berücksichtigt dabei verschiedene Faktoren, wie die Schwere der Tat, [[strafmildernde]] oder [[strafverschärfende]] Umstände sowie die persönlichen Verhältnisse des Täters"}, {"kategorie": "", "text": "Der Strafausspruch bildet somit den abschließenden Teil des [[Urteils]], in dem die rechtliche Konsequenz der Tat für den [[Verurteilten]] festgelegt wird."}]'::jsonb, ''),
  ('einauntwoatung', 'Einauntwoatung', '', '', '', '', 'Einantwortung', '[{"kategorie": "jur.", "text": "\"abschließender Akt im österreichischen [[Verlassenschaftsverfahren]], bei dem das Vermögen des Verstorbenen (die [[Verlassenschaft]]) offiziell und rechtlich an die [[Erben]] übertragen wird\""}, {"kategorie": "", "text": "Mit der Einantwortung wird das gesamte Vermögen des Verstorbenen auf die Erben übertragen, wodurch diese die vollständige [[Rechtsnachfolge]] antreten und sowohl die Rechte als auch die Pflichten (z. B. Schulden) des Verstorbenen übernehmen"}, {"kategorie": "", "text": "Die Einantwortung erfolgt erst, nachdem das Verlassenschaftsverfahren abgeschlossen ist. Dies beinhaltet die Feststellung der Erben und ihrer Erbberechtigung sowie gegebenenfalls die Klärung der Schulden und sonstiger Verbindlichkeiten des Verstorbenen"}, {"kategorie": "", "text": "Die Einantwortung wird durch einen Beschluss des zuständigen [[Verlassenschaftsgerichts]], das in der Regel durch einen Notar als Gerichtskommissär vertreten wird, verfügt. Das Gericht stellt fest, wer die Erben sind und wie der Nachlass verteilt wird"}, {"kategorie": "", "text": "Mit der Einantwortung gehen nicht nur die Vermögenswerte, sondern auch die Schulden des Verstorbenen auf die Erben über. Die Erben haften für die Verbindlichkeiten des Verstorbenen, wobei sie in bestimmten Fällen (z. B. bei bedingter Annahme der Erbschaft) die Haftung auf den Wert des Nachlasses beschränken können (siehe \"bedingte Erbantrittserklärung\")"}, {"kategorie": "", "text": "Mit der Einantwortung tritt der Erbe oder treten die Erben vollständig in die Rechtsstellung des Verstorbenen ein. Sie werden zu den neuen Eigentümern des [[Nachlasses]] und können über das vererbte Vermögen frei verfügen."}]'::jsonb, ''),
  ('einaunwoatungsuakundn', 'Einaunwoatungsuakundn', '', '', '', '', 'Einantwortungsurkunde', '[{"kategorie": "jur.", "text": "\"gerichtliches Dokument, das die formelle und rechtlich verbindliche Übertragung des [[Nachlasses]] einer verstorbenen Person auf die [[Erben]] im Rahmen des österreichischen [[Verlassenschaftsverfahrens]] bestätigt\""}, {"kategorie": "", "text": "Die Einantwortungsurkunde dient als Nachweis dafür, dass die Erben die [[Rechtsnachfolge]] des Verstorbenen angetreten haben und nun berechtigt sind, über das ererbte Vermögen zu verfügen"}, {"kategorie": "", "text": "Die Einantwortungsurkunde bestätigt, wer die rechtmäßigen Erben des Verstorbenen sind und welche Anteile sie am Nachlass erhalten. Sie dient als offizielle Urkunde, die von den Erben als Beweis für ihre Erbberechtigung genutzt werden kann"}, {"kategorie": "", "text": "Mit Ausstellung der Einantwortungsurkunde wird der Erbe bzw. werden die Erben rechtlich zu den neuen Eigentümern des Nachlasses. Diese Urkunde hat eine rechtskräftige Wirkung und stellt die vollständige Übertragung des Vermögens dar"}, {"kategorie": "", "text": "Durch die Einantwortungsurkunde erlangen die Erben das Recht, über das Vermögen des Verstorbenen zu verfügen, sei es Immobilien, Bankkonten, Wertpapiere oder andere Vermögenswerte"}, {"kategorie": "", "text": "Die Urkunde weist die Erben auch als Rechtsnachfolger für etwaige Schulden und Verbindlichkeiten des Verstorbenen aus. Damit können Gläubiger des Verstorbenen Ansprüche gegenüber den Erben geltend machen"}, {"kategorie": "", "text": "Die Einantwortungsurkunde wird vom Gericht nach Abschluss des Verlassenschaftsverfahrens ausgestellt und markiert den formalen Übergang des Nachlasses auf die Erben. Sie ist ein zentrales Dokument, das sowohl in rechtlichen als auch in administrativen Angelegenheiten (z. B. Grundbuchseintragungen oder Bankgeschäfte) verwendet wird."}]'::jsonb, ''),
  ('todesfoiaufnaume', 'Todesfoiaufnaume', '', '', '', '', 'Todesfallaufnahme', '[{"kategorie": "jur.", "text": "\"formeller Schritt im österreichischen [[Verlassenschaftsverfahren]], der unmittelbar nach dem Tod einer Person durchgeführt wird\""}, {"kategorie": "", "text": "Dabei handelt es sich um eine amtliche Erhebung durch einen [[Notar]] (als Gerichtskommissär) oder das zuständige [[Gericht]], um erste Informationen über den verstorbenen [[Erblasser]], sein Vermögen und mögliche [[Erben]] zu sammeln"}, {"kategorie": "", "text": "Ziel der Todesfallaufnahme ist es, den [[Nachlass]] zu erfassen und die rechtliche Grundlage für das weitere Verlassenschaftsverfahren zu schaffen"}, {"kategorie": "", "text": "Wichtige Inhalte der Todesfallaufnahme: (i) \nDaten des Verstorbenen: Die Identität des Verstorbenen wird festgestellt, einschließlich des Namens, Geburtsdatums, Sterbedatums und letzten Wohnsitzes;  (ii) Vermögensaufstellung: Es wird eine erste Übersicht über das vorhandene Vermögen des Verstorbenen erstellt. Dazu gehören etwa Immobilien, Bankguthaben, Wertpapiere oder andere Vermögensgegenstände. Auch Schulden und Verbindlichkeiten des Verstorbenen werden erfasst;  (iii) \n[[Testament]] und [[letztwillige]] Verfügungen: Falls ein Testament oder eine sonstige letztwillige Verfügung vorliegt, wird dies bei der Todesfallaufnahme dokumentiert. Falls kein Testament vorhanden ist, kommt die [[gesetzliche]] Erbfolge zur Anwendung;  (iv) Erben und Beteiligte: Mögliche Erben oder Personen, die am Nachlass beteiligt sind (z. B. [[Vermächtnisnehmer]]), werden festgehalten;  (v) Eröffnung des [[Verlassenschaftsverfahrens]]: Auf Basis der Todesfallaufnahme wird das Verlassenschaftsverfahren formell eröffnet, um den Nachlass rechtmäßig unter den Erben aufzuteilen"}, {"kategorie": "", "text": "Die Todesfallaufnahme bildet somit die Grundlage für die Abwicklung der Verlassenschaft und dient der geordneten und rechtlich abgesicherten Feststellung der Erben und des Nachlasses."}]'::jsonb, ''),
  ('valossnschoft', 'Valossnschoft', '', '', '', '', 'Verlassenschaft', '[{"kategorie": "jur.", "text": "\"das gesamte Vermögen und die Schulden, die eine verstorbene Person hinterlässt\""}, {"kategorie": "", "text": "Die \"Verlassenschaft\" entspricht damit dem [[Nachlass]], ist jedoch ein juristischer Begriff, der vor allem im Zusammenhang mit dem [[Verlassenschaftsverfahren]] verwendet wird"}, {"kategorie": "", "text": "Die Verlassenschaft umfasst alle Rechte und Verbindlichkeiten des Verstorbenen und stellt das Vermögen dar, das den [[Erben]] oder [[Vermächtnisnehmern]] zufällt"}, {"kategorie": "", "text": "Die Verlassenschaft umfasst:  (i) Vermögenswerte: alle beweglichen und unbeweglichen Güter des Verstorbenen, wie Immobilien, Bankguthaben, Wertpapiere, persönliche Gegenstände und sonstiges Eigentum;  (ii) Schulden und Verpflichtungen: Auch die Schulden des Verstorbenen, wie Kredite, offene Rechnungen oder finanzielle Verpflichtungen, gehören zur Verlassenschaft. Die Erben haften für diese Schulden, können aber unter bestimmten Voraussetzungen die Haftung auf den Wert des Nachlasses beschränken"}, {"kategorie": "", "text": "In Österreich wird die Verlassenschaft durch ein gerichtliches Verfahren abgewickelt, das von einem [[Notar]] als Gerichtskommissär geleitet wird. Ziel des Verfahrens ist es, den [[Nachlass]] zu ermitteln, die [[Erben]] zu bestimmen und den Nachlass ordnungsgemäß aufzuteilen. Dabei wird auch geprüft, ob ein [[Testament]] vorliegt und wie das Erbe aufgeteilt werden soll"}, {"kategorie": "", "text": "Sobald das [[Verlassenschaftsverfahren]] abgeschlossen ist und die Erben feststehen, wird die Verlassenschaft den Erben übergeben, die damit die Rechte und Pflichten aus der Verlassenschaft übernehmen (siehe [[Einantwortungsurkunde]])"}, {"kategorie": "", "text": "Die Verlassenschaft existiert rechtlich gesehen so lange, bis das [[Verlassenschaftsverfahren]] abgeschlossen und die [[Erbschaft]] angetreten oder ausgeschlagen wurde."}]'::jsonb, ''),
  ('valossnschoftsvafoan', 'Valossnschoftsvafoan', '', '', '', '', 'Verlassenschaftsverfahren', '[{"kategorie": "jur.", "text": "\"gesetzlich geregeltes gerichtliches Verfahren in Österreich, das die Abwicklung des Nachlasses einer verstorbenen Person betrifft\""}, {"kategorie": "", "text": "Es wird eingeleitet, um den [[Nachlass]] zu erfassen, die [[Erben]] zu bestimmen, die rechtmäßige Aufteilung des [[Erbes]] sicherzustellen und eventuelle Schulden des Verstorbenen zu regeln"}, {"kategorie": "", "text": "Das Verlassenschaftsverfahren wird von einem [[Notar]], der als Gerichtskommissär fungiert, im Auftrag des Gerichts durchgeführt"}, {"kategorie": "", "text": "Wichtige Schritte des Verlassenschaftsverfahrens:  (i) [[Todesfallaufnahme]]: Das Verfahren beginnt nach dem Tod einer Person mit der amtlichen Feststellung des Todes und der Todesfallaufnahme. Dabei werden die wichtigsten Daten zum Verstorbenen und dessen Vermögenssituation erhoben;  (ii) Einziehung und Sicherung des Nachlasses: Der Gerichtskommissär sammelt Informationen über die Vermögenswerte (Immobilien, Konten, Wertpapiere etc.) und Schulden des Verstorbenen. Falls erforderlich, wird der Nachlass gesichert, etwa um ihn vor unberechtigtem Zugriff zu schützen;  (iii) Feststellung der [[Erben]]: Im Rahmen des Verfahrens wird festgestellt, wer die Erben sind. Das kann durch ein [[Testament]] oder nach den [[gesetzlichen]] Erbfolgeregelungen geschehen. Der Notar klärt die Erbberechtigung und stellt die potenziellen Erben fest;  (iv) Erbenentscheidung: Die Erben werden über ihre Rechte und Pflichten informiert, einschließlich der Möglichkeit, die Erbschaft anzunehmen, bedingt anzunehmen (Haftung nur bis zur Höhe des Nachlasswerts) oder auszuschlagen (insbesondere bei überschuldetem Nachlass)"}, {"kategorie": "", "text": "Das Verlassenschaftsverfahren ist obligatorisch und stellt sicher, dass die Rechte der Erben gewahrt werden und die Abwicklung des Nachlasses rechtskonform erfolgt. Es ist darauf ausgelegt, Streitigkeiten über den Nachlass zu vermeiden und eine geordnete Vermögensübertragung zu gewährleisten."}]'::jsonb, ''),
  ('notar', 'Notar', '', '', '', '', 'Notar', '[{"kategorie": "jur.", "text": "\"unabhängige und unparteiische Person des öffentlichen Rechts, die in Österreich hoheitliche Aufgaben wahrnimmt und insbesondere in zivilrechtlichen Angelegenheiten tätig ist\""}, {"kategorie": "", "text": "Notare sind für die Beglaubigung und Beurkundung von Rechtsgeschäften, Willenserklärungen und Verträgen zuständig und sorgen dafür, dass diese rechtssicher und verbindlich sind"}, {"kategorie": "", "text": "Sie haben die Aufgabe, sowohl die [[Parteien]] als auch den [[Staat]] durch die Sicherstellung rechtskonformer Abläufe zu schützen"}, {"kategorie": "", "text": "Zu den Hauptaufgaben eines Notars gehören:  (i) Beurkundung: Notare erstellen und beglaubigen Urkunden, die bei bestimmten Rechtsgeschäften erforderlich sind. Dazu gehören etwa [[Eheverträge]], [[Erbverträge]], [[Testamente]], Grundstückskaufverträge oder Gründungen von Gesellschaften. Durch die [[notarielle]] Beurkundung wird das [[Rechtsgeschäft]] rechtskräftig und beweiskräftig gemacht;  (ii) Beglaubigung von Unterschriften: Notare beglaubigen die Echtheit von Unterschriften, was in vielen Rechtsgeschäften erforderlich ist, um die Identität der Unterzeichner zu bestätigen;  (iii) Verwahrung: Notare können Dokumente, Testamente oder Gelder treuhänderisch verwahren, bis diese im Rahmen eines Rechtsgeschäfts oder nach dem Tod einer Person benötigt werden;  (iv) Beratung: Notare beraten in rechtlichen Angelegenheiten, insbesondere in Bezug auf Immobiliengeschäfte, Erbrecht und Unternehmensgründungen. Sie sind dazu verpflichtet, neutral und unparteiisch zu agieren, um die Interessen aller beteiligten Parteien gleichermaßen zu wahren;  (v) Mediationsfunktion: In bestimmten Fällen können Notare auch als Vermittler oder Mediatoren fungieren, insbesondere bei einvernehmlichen Regelungen in Erbangelegenheiten oder familiären Rechtsfragen"}, {"kategorie": "", "text": "Notare spielen eine wichtige Rolle in der vorsorgenden [[Rechtspflege]]. Das bedeutet, sie wirken präventiv, um Rechtsstreitigkeiten zu vermeiden, indem sie sicherstellen, dass die getroffenen Vereinbarungen rechtlich einwandfrei sind. In Österreich sind Notare in ihrer Funktion unabhängig und unterstehen der Aufsicht des [[Staates]]."}]'::jsonb, ''),
  ('hypoteek', 'Hypoteek', '', '', '', '', 'Hypothek', '[{"kategorie": "jur.", "text": "\"dingliches Sicherungsrecht an einer Immobilie, das dem [[Gläubiger]] – in der Regel einer Bank – als Sicherheit für die Rückzahlung eines Darlehens dient\""}, {"kategorie": "", "text": "Wird das [[Darlehen]] nicht ordnungsgemäß zurückgezahlt, hat der Gläubiger das Recht, die Immobilie zu verwerten (z. B. durch [[Zwangsversteigerung]]), um die ausstehende Forderung zu begleichen"}, {"kategorie": "", "text": "Eine Hypothek ist ein Grundpfandrecht, das im [[Grundbuch]] eingetragen wird. Sie bezieht sich auf eine bestimmte Immobilie (z. B. ein Haus oder ein Grundstück) und bleibt auch bestehen, wenn der Eigentümer wechselt"}, {"kategorie": "", "text": "Hypotheken werden meist zur Sicherung eines Immobilienkredits genutzt. Der [[Kreditnehmer]] erhält von der Bank einen Kredit, und die Bank erhält als Sicherheit die Hypothek auf die Immobilie"}, {"kategorie": "", "text": "Die Hypothek muss im [[Grundbuch]] der betreffenden Immobilie eingetragen werden, um wirksam zu sein. Diese Eintragung erfolgt im C-Blatt (Lastenblatt) des Grundbuchs"}, {"kategorie": "", "text": "Wenn der Kreditnehmer das Darlehen nicht zurückzahlen kann, hat der Gläubiger das Recht, die Immobilie zu versteigern oder anderweitig zu verwerten, um die Schulden zu decken"}, {"kategorie": "", "text": "Sobald der Kredit vollständig zurückgezahlt ist, kann die Hypothek im Grundbuch gelöscht werden. Der Eigentümer muss hierfür einen Antrag stellen, der von der Bank bestätigt wird."}]'::jsonb, ''),
  ('pfaendungsauntrog', 'Pfändungsauntrog', '', '', '', '', 'Pfändungsantrag', '[{"kategorie": "jur.", "text": "\"formeller Antrag, den ein [[Gläubiger]] bei [[Gericht]] stellt, um eine [[Zwangsvollstreckung]] gegen einen [[Schuldner]] zu erwirken\""}, {"kategorie": "", "text": "Mit diesem Antrag möchte der Gläubiger erreichen, dass das Vermögen des Schuldners (z. B. Lohn, Konto, bewegliche Sachen) gepfändet wird, um eine offene Forderung zu begleichen. Der Pfändungsantrag ist ein wesentlicher Schritt im Vollstreckungsverfahren, wenn der Schuldner seine Schulden nicht freiwillig begleicht"}, {"kategorie": "", "text": "Voraussetzung für die Stellung eines Pfändungsantrags ist, dass der Gläubiger einen [[vollstreckbaren]] Titel besitzt. Das kann ein gerichtliches [[Urteil]], ein [[Vollstreckungsbescheid]] oder eine notarielle Urkunde sein, die die Forderung des Gläubigers gegenüber dem Schuldner rechtskräftig feststellt"}, {"kategorie": "", "text": "Mit dem Pfändungsantrag beantragt der Gläubiger die Durchführung der Zwangsvollstreckung, um sein Geld einzutreiben. Dies kann die Pfändung von Lohn, Gehalt, Kontoguthaben oder anderen Vermögenswerten des Schuldners umfassen"}, {"kategorie": "", "text": "Der Pfändungsantrag wird bei dem zuständigen Gericht gestellt, in der Regel beim [[Vollstreckungsgericht]]. Das Gericht prüft den Antrag, und wenn die Voraussetzungen gegeben sind, erlässt es einen [[Pfändungs-]] und Überweisungsbeschluss"}, {"kategorie": "", "text": "Nach dem [[Beschluss]] des Gerichts wird die [[Pfändung]] durch einen [[Gerichtsvollzieher]] oder direkt durch den Arbeitgeber (bei [[Lohnpfändung]]) oder die Bank (bei [[Kontopfändung]]) durchgeführt. Diese sind dann verpflichtet, den gepfändeten Betrag an den Gläubiger auszuzahlen"}, {"kategorie": "", "text": "Der Pfändungsantrag muss genaue Angaben zur Forderung, zum Schuldner und zu den pfändbaren Vermögenswerten enthalten. Zudem muss der Gläubiger in der Regel vorab versucht haben, den Schuldner zur freiwilligen Zahlung zu bewegen."}]'::jsonb, ''),
  ('loonpfaendung', 'Loonpfändung', '', '', '', '', 'Lohnpfändung', '[{"kategorie": "jur.", "text": "\"Maßnahme der [[Zwangsvollstreckung]], bei der ein Teil des Arbeitseinkommens eines [[Schuldners]] gepfändet wird, um eine offene Forderung eines [[Gläubigers]] zu begleichen\""}, {"kategorie": "", "text": "Die Lohnpfändung erfolgt auf Grundlage eines gerichtlichen Beschlusses. Der Gläubiger muss beim zuständigen Gericht einen [[Pfändungsantrag]] stellen und einen [[vollstreckbaren]] Titel (z. B. ein Urteil) haben, der die Forderung bestätigt"}, {"kategorie": "", "text": "Gepfändet werden in der Regel der Lohn, das Gehalt oder ähnliche Einkünfte, die der Schuldner aus seiner beruflichen Tätigkeit bezieht. Andere Einnahmen, wie Renten oder Sozialleistungen, können unter bestimmten Bedingungen ebenfalls gepfändet werden"}, {"kategorie": "", "text": "Bei einer Lohnpfändung darf nicht das gesamte Einkommen des Schuldners gepfändet werden. Es gibt eine gesetzlich festgelegte [[Pfändungsfreigrenze]], die den Betrag festlegt, der dem Schuldner für seinen Lebensunterhalt und den seiner Familie verbleiben muss. Diese Grenze variiert je nach Einkommen und Anzahl der unterhaltsberechtigten Personen"}, {"kategorie": "", "text": "Der pfändbare Betrag ist der Teil des Einkommens, der oberhalb der Pfändungsfreigrenze liegt. Dieser Betrag wird vom Arbeitgeber direkt an den Gläubiger überwiesen, bis die Forderung vollständig beglichen ist"}, {"kategorie": "", "text": "Der Arbeitgeber des Schuldners wird zum sogenannten [[Drittschuldner]], da er verpflichtet ist, den gepfändeten Lohn direkt an den Gläubiger auszuzahlen und nicht an den Schuldner."}]'::jsonb, ''),
  ('pfaundrecht', 'Pfaundrecht', '', '', '', '', 'Pfandrecht', '[{"kategorie": "jur.", "text": "\"dingliches Sicherungsrecht, das einem [[Gläubiger]] das Recht gibt, eine Sache oder ein Recht eines Schuldners als Sicherheit für eine Forderung zu nutzen\""}, {"kategorie": "", "text": "Das Pfandrecht wird in der Regel zur Sicherung einer Geldforderung bestellt. Es gewährt dem Gläubiger das Recht, sich aus dem Wert des Pfandgegenstands zu befriedigen, wenn der Schuldner die zugrunde liegende Verpflichtung nicht erfüllt"}, {"kategorie": "", "text": "Als [[Pfand]] kann sowohl eine bewegliche Sache (z. B. Schmuck, Fahrzeuge) als auch eine unbewegliche Sache (z. B. Immobilien) oder ein Recht (z. B. Forderungen, Patente) dienen. Im Fall von Immobilien wird das Pfandrecht als [[Hypothek]] bezeichnet"}, {"kategorie": "", "text": "Wenn der Schuldner seine Verbindlichkeiten nicht begleicht, hat der Gläubiger das Recht, die verpfändete Sache oder das verpfändete Recht zu verkaufen oder zu versteigern, um die offene Forderung zu begleichen. Der Gläubiger ist jedoch verpflichtet, den verbleibenden Überschuss an den Schuldner auszuzahlen"}, {"kategorie": "", "text": "Je nach Art des Pfandrechts kann es erforderlich sein, das Pfandrecht in ein öffentliches Register, wie das [[Grundbuch]] bei Immobilien, einzutragen (z. B. Hypothek), oder die Pfandsache an den Gläubiger zu übergeben (bei einem [[Faustpfand]])"}, {"kategorie": "", "text": "Das Pfandrecht erlischt, sobald die zugrunde liegende Forderung vollständig erfüllt ist. In der Regel wird die Pfandsache dann an den Schuldner zurückgegeben oder das Pfandrecht im Register gelöscht."}]'::jsonb, ''),
  ('faustpfaund', 'Faustpfaund', '', '', '', '', 'Faustpfand', '[{"kategorie": "jur.", "text": "\"spezielle Form des [[Pfandrechts]], bei der eine bewegliche Sache (also eine Sache, die physisch bewegbar ist) als Sicherheit für eine Forderung dient\""}, {"kategorie": "", "text": "Der wesentliche Unterschied zum allgemeinen Pfandrecht besteht darin, dass die verpfändete bewegliche Sache tatsächlich an den [[Gläubiger]] oder einen Dritten übergeben wird. Der [[Schuldner]] verliert den unmittelbaren Besitz an der Sache, behält aber das Eigentum daran"}, {"kategorie": "", "text": "Das Faustpfand dient als Sicherheit für eine Forderung. Der Gläubiger behält die Pfandsache in seinem Besitz, bis der Schuldner die ihm gegenüber bestehende Verpflichtung, in der Regel eine Zahlung, erfüllt"}, {"kategorie": "", "text": "Kommt der Schuldner seinen Verpflichtungen nicht nach, hat der Gläubiger das Recht, das Faustpfand zu verwerten, meist durch Verkauf oder Versteigerung, um seine Forderung zu begleichen. Der Erlös wird zur Deckung der Schuld verwendet, ein möglicher Überschuss wird dem Schuldner zurückerstattet"}, {"kategorie": "", "text": "In Österreich ist das Faustpfand im [[Allgemeinen]] Bürgerlichen Gesetzbuch (ABGB) geregelt. Das Pfandrecht entsteht durch die Übergabe der Pfandsache (Besitzwechsel) und erlischt, sobald die zugrunde liegende Forderung beglichen ist"}, {"kategorie": "", "text": "Ein typisches Beispiel für ein Faustpfand ist die Verpfändung von Wertsachen wie Schmuck oder Kunstwerken an eine Bank oder ein Pfandhaus, um ein [[Darlehen]] zu erhalten"}, {"kategorie": "", "text": "Das Faustpfand bietet dem Gläubiger eine höhere Sicherheit, da die Pfandsache in seinem Besitz verbleibt und er im Falle der Nichterfüllung der Schuld direkt darauf zugreifen kann."}]'::jsonb, ''),
  ('pfaund', 'Pfaund', '', '', '', '', 'Pfand', '[{"kategorie": "jur.", "text": "\"Sicherungsrecht, bei dem der [[Gläubiger]] eine Sache oder ein Recht als Sicherheit erhält, um seine Forderung abzusichern\""}, {"kategorie": "", "text": "Das Pfand dient dazu, dem Gläubiger das Recht zu geben, im Falle der Nichterfüllung einer Verpflichtung, in der Regel der Zahlung einer Geldschuld, die verpfändete Sache oder das verpfändete Recht zu verwerten (z. B. durch Verkauf oder Versteigerung), um die ausstehende Forderung zu begleichen"}, {"kategorie": "", "text": "Als Pfand können sowohl bewegliche Sachen (z. B. Schmuck, Fahrzeuge) als auch unbewegliche Sachen (Immobilien, die dann in der Regel als Hypothek belastet werden) dienen. Auch Rechte, wie etwa Forderungen oder Patente, können verpfändet werden"}, {"kategorie": "", "text": "Beim [[Faustpfand]] erhält der Gläubiger den Besitz der Pfandsache, während sie im Eigentum des Schuldners bleibt. Der Schuldner hat die Möglichkeit, die Pfandsache zurückzuerlangen, sobald er seine Verpflichtung erfüllt. Kommt er dieser nicht nach, darf der Gläubiger die Pfandsache verwerten, um seine Forderung zu befriedigen"}, {"kategorie": "", "text": "Wenn der Schuldner seine Schulden nicht begleicht, kann der Gläubiger das Pfand verkaufen oder versteigern lassen. Der Erlös wird dann zur Tilgung der Forderung verwendet. Ein möglicher Überschuss muss an den Schuldner ausgezahlt werden"}, {"kategorie": "", "text": "Die rechtliche Regelung eines Pfandrechts ist im österreichischen [[Zivilrecht]], insbesondere im [[Allgemeinen]] Bürgerlichen Gesetzbuch (ABGB), festgelegt. Ein Pfandrecht wird entweder durch vertragliche Vereinbarung oder kraft Gesetzes (z. B. bei bestimmten Steuerforderungen) begründet."}]'::jsonb, ''),
  ('schuidvahoetnis', 'Schuidvahötnis', '', '', '', '', 'Schuldverhältnis', '[{"kategorie": "jur.", "text": "\"rechtlicher Begriff, der das Verhältnis zwischen einem [[Gläubiger]] und einem [[Schuldner]] beschreibt, in dem der Schuldner verpflichtet ist, eine bestimmte Leistung zu erbringen (Zahlung eines Geldbetrags, Lieferung von Waren, Erbringung einer Dienstleistung, etc.), und der Gläubiger das Recht hat, diese Leistung einzufordern\""}, {"kategorie": "", "text": "Ein Schuldverhältnis entsteht in der Regel durch einen Vertrag (z. B. Kaufvertrag, Mietvertrag, Darlehensvertrag), kann aber auch durch gesetzliche Regelungen (z. B. Schadensersatzansprüche, ungerechtfertigte Bereicherung) oder durch gerichtliche Entscheidungen begründet werden"}, {"kategorie": "", "text": "In einem Schuldverhältnis bestehen primäre Pflichten, wie die Erfüllung einer vertraglich vereinbarten Leistung, und sekundäre Pflichten, die bei der Nichterfüllung der primären Pflichten entstehen, wie Schadensersatzforderungen oder Rücktrittsrechte"}, {"kategorie": "", "text": "Das Schuldverhältnis endet in der Regel, sobald die geschuldete Leistung vollständig erbracht wurde. In bestimmten Fällen kann das Schuldverhältnis auch durch Aufhebung, Rücktritt oder Kündigung beendet werden."}]'::jsonb, ''),
  ('schuidna', 'Schuidna', '', '', '', '', 'Schuldner', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person, die gegenüber einem [[Gläubiger]] verpflichtet ist, eine bestimmte Leistung zu erbringen\""}, {"kategorie": "", "text": "Der Schuldner ist verpflichtet, eine vertraglich oder gesetzlich festgelegte Leistung zu erbringen. Diese kann in der Zahlung eines Geldbetrags, der Übergabe von Waren oder der Durchführung einer bestimmten Handlung bestehen"}, {"kategorie": "", "text": "Die Beziehung zwischen Schuldner und Gläubiger basiert auf einem [[Schuldverhältnis]], das durch Vertrag, Gesetz oder andere Rechtsgrundlagen entstehen kann. Beispielsweise entsteht ein Schuldverhältnis durch einen Kreditvertrag oder eine Kaufvereinbarung"}, {"kategorie": "", "text": "Der Schuldner muss die geschuldete Leistung rechtzeitig und in der vereinbarten Form erbringen, um die Verpflichtung zu erfüllen und das Schuldverhältnis zu beenden"}, {"kategorie": "", "text": "Wenn der Schuldner seiner Leistungspflicht nicht nachkommt, kann der Gläubiger rechtliche Schritte einleiten, um die Forderung durchzusetzen. Dies kann bis zur [[Zwangsvollstreckung]] führen, bei der Vermögenswerte des Schuldners gepfändet oder verkauft werden"}, {"kategorie": "", "text": "Schulden können finanzieller Art sein (z. B. Darlehensrückzahlungen), aber auch andere Verpflichtungen umfassen, wie die Lieferung von Waren oder das Erbringen von Dienstleistungen."}]'::jsonb, ''),
  ('gerichtsvoiziiha', 'Gerichtsvoiziiha', '', '', '', '', 'Gerichtsvollzieher', '[{"kategorie": "jur.", "text": "\"Beamter des Gerichts, der im Rahmen der [[Zwangsvollstreckung]] tätig wird\""}, {"kategorie": "", "text": "Seine Hauptaufgabe besteht darin, gerichtliche Entscheidungen, insbesondere in Bezug auf die Vollstreckung von Geldforderungen oder anderen Ansprüchen, durchzusetzen"}, {"kategorie": "", "text": "Der Gerichtsvollzieher sorgt dafür, dass der [[Gläubiger]] seine Forderung gegenüber einem [[Schuldner]] durch pfändbare Vermögenswerte befriedigen kann"}, {"kategorie": "", "text": "Der Gerichtsvollzieher führt Pfändungen von Vermögenswerten des Schuldners durch, wie etwa [[Lohnpfändungen]], [[Sachpfändungen]] oder [[Kontopfändungen]], um offene Forderungen des Gläubigers zu sichern"}, {"kategorie": "", "text": "Er beschlagnahmt bewegliche Sachen (z. B. Wertsachen, Fahrzeuge) und veranlasst deren Verwertung, etwa durch Versteigerung, um den Erlös zur Begleichung der Schulden zu verwenden"}, {"kategorie": "", "text": "Gerichtsvollzieher stellen auch wichtige gerichtliche Dokumente, wie [[Mahnbescheide]], Vollstreckungstitel oder andere rechtlich relevante Schriftstücke, dem Schuldner zu"}, {"kategorie": "", "text": "Gerichtsvollzieher führen auch [[Räumungen]] durch, wenn ein Mieter auf Grundlage eines [[Räumungstitels]] aus einer Immobilie entfernt werden muss"}, {"kategorie": "", "text": "Gerichtsvollzieher erstellen Protokolle über den Verlauf der Zwangsvollstreckungsmaßnahmen. Diese Protokolle dienen als Nachweis für die ordnungsgemäße Durchführung der Vollstreckung"}, {"kategorie": "", "text": "In bestimmten Fällen sorgt der Gerichtsvollzieher dafür, dass Schuldnerrechte gewahrt werden, wie etwa die Beachtung von [[Pfändungsfreigrenzen]] oder die Unpfändbarkeit bestimmter Gegenstände (z. B. notwendiger Hausrat)."}]'::jsonb, ''),
  ('gsoeschoftsrecht', 'Gsöschoftsrecht', '', '', '', '', 'Gesellschaftsrecht', '[{"kategorie": "jur.", "text": "\"jener Teil des Rechts, der die Gründung, Organisation, Führung und Auflösung von Gesellschaften regelt\""}, {"kategorie": "", "text": "Es umfasst die gesetzlichen Bestimmungen und Vorschriften, die die Rechtsverhältnisse von Gesellschaften, wie z. B. Unternehmen, Personengesellschaften oder Kapitalgesellschaften, regeln und deren Beziehungen zu den Gesellschaftern, Gläubigern und Dritten festlegen"}, {"kategorie": "", "text": "Das Gesellschaftsrecht spielt eine zentrale Rolle im Wirtschaftsleben, da es den rechtlichen Rahmen für Unternehmensgründungen, -strukturen und -tätigkeiten bietet"}, {"kategorie": "", "text": "Gesellschaftsformen: Das Gesellschaftsrecht regelt verschiedene Rechtsformen von Gesellschaften, die sich in ihrer Struktur, Haftung und Besteuerung unterscheiden. Zu den wichtigsten Gesellschaftsformen gehören:  (i) [[Personengesellschaften]]: Wie die [[Offene]] Gesellschaft (OG) oder die [[Kommanditgesellschaft]] (KG), bei denen die Gesellschafter in der Regel persönlich und unbeschränkt haften;  (ii) [[Kapitalgesellschaften]]: Wie die [[Gesellschaft]] mit beschränkter Haftung (GmbH) oder die [[Aktiengesellschaft]] (AG), bei denen die Haftung auf das Gesellschaftsvermögen beschränkt ist und die Gesellschafter nicht mit ihrem persönlichen Vermögen haften;  (iii) Genossenschaften und Vereine sind ebenfalls von Bedeutung, insbesondere im Bereich der Kooperation und Zusammenarbeit mehrerer Personen oder Unternehmen"}, {"kategorie": "", "text": "Das Gesellschaftsrecht regelt, wer die Gesellschaft nach außen hin vertritt und die [[Geschäftsführung]] übernimmt. In Kapitalgesellschaften sind dies oft [[Geschäftsführer]] oder [[Vorstände]], während in Personengesellschaften die Gesellschafter selbst die Geschäfte führen"}, {"kategorie": "", "text": "[[Gewinnverteilung]] und [[Verlustbeteiligung]]: Die Verteilung von Gewinnen und die Beteiligung an Verlusten wird im Gesellschaftsrecht geregelt und hängt von der gewählten Gesellschaftsform und den Vereinbarungen im Gesellschaftsvertrag ab"}, {"kategorie": "", "text": "Corporate Governance: Das Gesellschaftsrecht umfasst auch Regelungen zur [[Corporate]] Governance, die festlegen, wie die Gesellschaft intern organisiert ist, wie Entscheidungen getroffen werden und welche Kontrollmechanismen existieren (z. B. [[Aufsichtsräte]], [[Hauptversammlungen]])"}, {"kategorie": "", "text": "Das Gesellschaftsrecht enthält auch Vorschriften zur [[Umwandlung]], [[Verschmelzung]] oder [[Spaltung]] von Gesellschaften. Diese Prozesse ermöglichen es Gesellschaften, ihre Struktur zu ändern, ohne die Gesellschaft vollständig aufzulösen"}, {"kategorie": "", "text": "Ein Teil des Gesellschaftsrechts befasst sich auch mit den rechtlichen Bestimmungen, die im Falle der [[Insolvenz]] einer Gesellschaft gelten, um die Rechte von Gläubigern und Gesellschaftern zu schützen und die geordnete Abwicklung der Gesellschaft zu gewährleisten."}]'::jsonb, ''),
  ('freibetroog', 'Freibetroog', '', '', '', '', 'Freibetrag', '[{"kategorie": "jur.", "text": "\"festgelegter Betrag, der bei der Berechnung von Steuern oder Sozialabgaben vom Einkommen oder Vermögen abgezogen wird, bevor die zu zahlende Steuer oder Abgabe ermittelt wird\""}, {"kategorie": "", "text": "Der Freibetrag stellt sicher, dass ein Teil des Einkommens oder Vermögens steuerfrei bleibt oder bei der Berechnung von Sozialleistungen unberücksichtigt bleibt"}, {"kategorie": "", "text": "In bestimmten Fällen wird der Freibetrag auch verwendet, um sicherzustellen, dass einem Schuldner bei Pfändungen ein Existenzminimum verbleibt"}, {"kategorie": "", "text": "Arten von Freibeträgen:  (i) Grundfreibetrag: Ein allgemeiner Betrag, der jedem Steuerpflichtigen zusteht und das steuerfreie Existenzminimum abdeckt;  (ii) Kinderfreibetrag: Ein Freibetrag, der Eltern gewährt wird, um die Kosten für die Versorgung ihrer Kinder zu mindern;  (iii) Werbungskostenpauschbetrag: Ein Pauschalbetrag, der zur Minderung der steuerlichen Belastung bei berufsbedingten Aufwendungen angerechnet wird;  (iv) Freibetrag bei Erbschaft: Bei der Erbschafts- oder Schenkungssteuer gibt es ebenfalls Freibeträge, die sicherstellen, dass ein bestimmter Teil der Erbschaft oder Schenkung steuerfrei bleibt;  (iv) Pfändungsfreibetrag: Ein Freibetrag wird auch im Rahmen von Pfändungen verwendet, um sicherzustellen, dass der Schuldner einen Teil seines Einkommens oder Vermögens behalten darf. Dieser Betrag dient dem Schutz des [[Existenzminimums]] und darf nicht gepfändet werden. Er gewährleistet, dass dem Schuldner genug Mittel für seinen Lebensunterhalt verbleiben"}, {"kategorie": "", "text": "Bei der Bedürftigkeitsprüfung für Sozialhilfe oder andere Sozialleistungen wird ein Freibetrag angewendet, damit bestimmte Vermögenswerte oder Einkommensteile, wie z. B. eine angemessene Altersvorsorge, nicht in die Berechnung einfließen. Dadurch wird sichergestellt, dass ein Mindestvermögen oder -einkommen unberücksichtigt bleibt."}]'::jsonb, ''),
  ('subsidiaritaetsprinzip', 'Subsidiaritätsprinzip', '', '', '', '', 'Subsidiaritätsprinzip', '[{"kategorie": "jur.", "text": "\"grundlegendes Prinzip im Sozial- und Verwaltungsrecht, das besagt, dass eine höhere staatliche Instanz oder übergeordnete Organisation erst dann eingreifen soll, wenn kleinere Einheiten oder die betroffene Person selbst nicht in der Lage sind, ein Problem zu lösen oder den Lebensunterhalt zu sichern.\""}, {"kategorie": "", "text": "Dieses Prinzip fördert Eigenverantwortung und Selbsthilfe und stellt sicher, dass staatliche Unterstützung nur dann gewährt wird, wenn die Möglichkeiten der Selbsthilfe oder der Hilfe durch kleinere Einheiten (z. B. Familie, Gemeinde) ausgeschöpft sind"}, {"kategorie": "", "text": "Das Subsidiaritätsprinzip wird in vielen Bereichen angewendet, insbesondere in:  (i) Sozialrecht: Sozialleistungen wie [[Sozialhilfe]] werden nach dem Subsidiaritätsprinzip gewährt. Das bedeutet, dass staatliche Leistungen erst in Anspruch genommen werden können, wenn der Einzelne seinen Lebensunterhalt nicht selbst bestreiten kann;  (ii) Verwaltung: In föderalen Systemen wie Österreich sollen Entscheidungen und Maßnahmen, wenn möglich, auf der lokal niedrigsten Ebene getroffen werden (z. B. Gemeinden), bevor die nächsthöhere staatliche Ebene eingreift;  (iii) EU-Recht: In der Europäischen Union bedeutet das Subsidiaritätsprinzip, dass die EU nur dann tätig wird, wenn die Mitgliedstaaten das Problem nicht selbst lösen können oder wenn eine gemeinsame Lösung effektiver ist."}]'::jsonb, ''),
  ('bedueaftigkeitspruefung', 'Bedüaftigkeitsprüfung', '', '', '', '', 'Bedürftigkeitsprüfung', '[{"kategorie": "jur.", "text": "\"Verfahren, bei dem geprüft wird, ob eine Person oder ein Haushalt finanziell hilfsbedürftig ist und Anspruch auf staatliche Unterstützungsleistungen, wie z. B. [[Sozialhilfe]], [[Wohnbeihilfe]] oder [[Pflegegeld]], hat\""}, {"kategorie": "", "text": "Dabei wird ermittelt, ob die betreffende Person ihren Lebensunterhalt oder spezifische Kosten (z. B. für Miete, Gesundheit, Pflege) aus eigenen Mitteln oder durch andere Einkommensquellen bestreiten kann"}, {"kategorie": "", "text": "Wichtige Merkmale der Bedürftigkeitsprüfung:  (i) Einkommensprüfung: Bei der Bedürftigkeitsprüfung wird das Einkommen der betroffenen Person oder des Haushalts detailliert untersucht. Dazu gehören Einkommen aus Erwerbstätigkeit, Renten, Sozialleistungen und andere regelmäßige Einnahmen. Ziel ist es, festzustellen, ob das Einkommen ausreicht, um den Lebensunterhalt zu sichern;  (ii) Vermögensprüfung: Neben dem Einkommen wird auch das vorhandene Vermögen geprüft. Dazu zählen Ersparnisse, Immobilien oder andere wertvolle Güter. In der Regel müssen Personen, die über ausreichendes Vermögen verfügen, dieses zunächst zur Deckung ihres Lebensunterhalts verwenden, bevor sie staatliche Unterstützung erhalten;  (iii) Berücksichtigung von Freibeträgen: Bei der Bedürftigkeitsprüfung gibt es in der Regel Freibeträge, die sicherstellen, dass den betroffenen Personen ein gewisses Existenzminimum bleibt, auch wenn sie Vermögen besitzen. Einige Vermögenswerte, wie eine angemessene Altersvorsorge oder bestimmte Haushaltsgegenstände, sind unpfändbar und bleiben bei der Prüfung unberücksichtigt"}, {"kategorie": "", "text": "Die Bedürftigkeitsprüfung folgt dem [[Subsidiaritätsprinzip]]. Das bedeutet, dass staatliche Leistungen erst dann gewährt werden, wenn keine anderen Ressourcen (Einkommen, Vermögen, familiäre Unterstützung) zur Verfügung stehen"}, {"kategorie": "", "text": "Eine einmal gewährte Leistung, die auf einer Bedürftigkeitsprüfung beruht, wird oft regelmäßig überprüft, um festzustellen, ob sich die finanzielle Situation der betroffenen Person verändert hat und ob die Unterstützung weiterhin erforderlich ist."}]'::jsonb, ''),
  ('sozialhueuefeleistungan', 'Sozialhüüfeleistungan', '', '', '', '', 'Sozialhilfeleistungen', '[{"kategorie": "jur.", "text": "\"inanzielle oder sachliche Unterstützungen, die vom [[Staat]] gewährt werden, um Personen in Notlagen zu helfen, die ihren Lebensunterhalt nicht selbst bestreiten können\""}, {"kategorie": "", "text": "Sozialhilfeleistungen werden in der Regel als letztes Mittel bereitgestellt, wenn alle anderen sozialen Sicherungssysteme, wie z. B. [[Arbeitslosengeld]] oder [[Pensionen]], nicht greifen oder nicht ausreichen"}, {"kategorie": "", "text": "Ziel der Sozialhilfe ist es, ein menschenwürdiges [[Existenzminimum]] zu gewährleisten und soziale Notlagen zu lindern"}, {"kategorie": "", "text": "Sozialhilfeleistungen sind darauf ausgelegt, den grundlegenden Lebensbedarf einer Person zu sichern, einschließlich Ausgaben für Nahrung, Kleidung, Unterkunft, Gesundheit und persönliche Pflege. Sie gewährleisten das Existenzminimum, das notwendig ist, um ein menschenwürdiges Leben zu führen"}, {"kategorie": "", "text": "Um Sozialhilfeleistungen zu erhalten, muss die Bedürftigkeit der antragstellenden Person nachgewiesen werden. Das bedeutet, dass die eigenen Einkommens- und Vermögensverhältnisse geprüft werden. Personen erhalten nur dann Sozialhilfe, wenn sie nicht in der Lage sind, ihren Lebensunterhalt aus eigener Kraft zu decken (siehe [[Bedürftigkeitsprüfung]])"}, {"kategorie": "", "text": "Sozialhilfeleistungen umfassen oft Geldleistungen, die den Lebensunterhalt der bedürftigen Person sicherstellen sollen. Dazu gehören beispielsweise:  (i) \n[[Grundsicherung]] oder [[Mindestsicherung]]: Regelmäßige finanzielle Unterstützung zur Deckung des allgemeinen Lebensbedarfs;  (ii) [[Wohnbeihilfen]]: Unterstützung bei Mietzahlungen oder Wohnkosten;  (iii) Einmalzahlungen: Für besondere Bedarfe oder Notlagen, wie z. B. für Möbel, Heizkosten oder Kleidung;  (iv) Sachleistungen: Neben finanziellen Hilfen können Sozialhilfeleistungen auch in Form von Sachleistungen erbracht werden. Dazu gehören die Bereitstellung von Wohnraum, medizinische Versorgung, Pflegeleistungen oder auch die Gewährung von Lebensmitteln und Kleidung;  (v) Gesundheits- und Pflegeleistungen: Bedürftige Personen, die Sozialhilfe erhalten, können auch Anspruch auf Gesundheits- und Pflegeleistungen haben. Das umfasst die Übernahme von Krankheitskosten, Rehabilitationsmaßnahmen oder Pflegehilfe, wenn die Person nicht in der Lage ist, diese Kosten selbst zu tragen;  (vi) \nSonderleistungen: In besonderen Situationen können zusätzliche Sozialhilfeleistungen gewährt werden, z. B. Unterstützung für Familien mit Kindern, Hilfe für pflegebedürftige Personen oder spezielle Maßnahmen für ältere Menschen"}, {"kategorie": "", "text": "Die [[Sozialhilfeträger]] (meist die Gemeinden, Länder oder zuständigen Sozialämter) verwalten und gewähren die Sozialhilfeleistungen. In Österreich sind die Regelungen zur Sozialhilfe auf Länderebene unterschiedlich, weshalb es keine einheitliche Regelung gibt. Stattdessen gibt es länderspezifische Gesetze, die die Mindestsicherung regeln"}, {"kategorie": "", "text": "Sozialhilfe wird nach dem [[Subsidiaritätsprinzip]] gewährt, was bedeutet, dass sie nur dann zum Tragen kommt, wenn keine anderen Einkommensquellen oder soziale Sicherungssysteme zur Verfügung stehen. Bevor Sozialhilfe in Anspruch genommen wird, muss der Antragsteller alle anderen Möglichkeiten ausschöpfen (z.B. [[Arbeitslosengeld]], [[Notstandshilfe]], [[Pension]])."}]'::jsonb, ''),
  ('sozialvasicharungsrecht', 'Sozialvasicharungsrecht', '', '', '', '', 'Sozialversicherungsrecht', '[{"kategorie": "jur.", "text": "\"Teil des öffentlichen Rechts, der die gesetzlichen Grundlagen und Regelungen für die Sozialversicherungssysteme umfasst\""}, {"kategorie": "", "text": "Es dient der rechtlichen Absicherung von Personen in Fällen von Krankheit, Arbeitsunfall, Invalidität, Alter oder Tod, indem es die Rechte und Pflichten der Versicherten und der Sozialversicherungsträger regelt"}, {"kategorie": "", "text": "Ziel des Sozialversicherungsrechts ist es, soziale Risiken abzufangen und die Lebensgrundlagen der Versicherten zu sichern"}, {"kategorie": "", "text": "Das Sozialversicherungsrecht definiert die Struktur, Aufgaben und Funktionsweise der verschiedenen Sozialversicherungszweige:  (i) Krankenversicherung: Absicherung im Krankheitsfall, Gewährung von medizinischen Leistungen und Krankengeld;  (ii) Unfallversicherung: Absicherung bei Arbeitsunfällen und Berufskrankheiten, Gewährung von Unfallrenten und Rehabilitationsmaßnahmen;  (iii) Pensionsversicherung: Gewährung von Alters- und Invaliditätspensionen sowie Hinterbliebenenleistungen;  (iv) Pflegeversicherung: Unterstützung von pflegebedürftigen Personen durch Pflegegeld und Sachleistungen;  (v) Pflichtversicherung: Das Sozialversicherungsrecht legt fest, wer pflichtversichert ist. In Österreich sind bestimmte Berufsgruppen, wie Arbeitnehmer, Selbstständige und Beamte, automatisch in den Sozialversicherungssystemen versichert"}, {"kategorie": "", "text": "Die Regelungen bestimmen, wer versichert ist, welche Beiträge zu leisten sind und welche Leistungen die Versicherten im Gegenzug erhalten"}, {"kategorie": "", "text": "Im Sozialversicherungsrecht ist festgelegt, welche Leistungen die Versicherten bei Eintritt eines Versicherungsfalls (z. B. Krankheit, Unfall, Pension) beanspruchen können. Dazu gehören Sachleistungen (wie ärztliche Behandlung, Krankenhausaufenthalte) und Geldleistungen (wie Krankengeld, Pensionen oder Pflegegeld)"}, {"kategorie": "", "text": "Das Sozialversicherungsrecht regelt die Beitragspflicht der Versicherten und Arbeitgeber. Es legt fest, wie viel von den Versicherten und ihren Arbeitgebern in die Sozialversicherung eingezahlt werden muss, und bestimmt die Höhe der [[Sozialversicherungsbeiträge]], die sich in der Regel nach dem Einkommen richten"}, {"kategorie": "", "text": "Das Sozialversicherungsrecht legt fest, unter welchen Bedingungen und Voraussetzungen eine Person Anspruch auf bestimmte Leistungen hat, z. B. durch Erfüllung der Mindestversicherungszeiten oder -beiträge, die im System der [[Pensionsversicherung]] gelten"}, {"kategorie": "", "text": "Es regelt auch die Rechte und Pflichten der [[Sozialversicherungsträger]], wie z. B. die [[Österreichische]] Gesundheitskasse (ÖGK), die [[Pensionsversicherungsanstalt]] (PVA) oder die [[Allgemeine]] Unfallversicherungsanstalt (AUVA). Diese Träger führen die Aufgaben der Sozialversicherung durch, erheben die Beiträge und gewähren die Versicherungsleistungen."}]'::jsonb, ''),
  ('sozialhueuefetraega', 'Sozialhüüfeträga', '', '', '', '', 'Sozialhilfeträger', '[{"kategorie": "jur.", "text": "\" öffentliche Institution oder Behörde, die für die Gewährung und Verwaltung von Sozialhilfeleistungen zuständig ist\""}, {"kategorie": "", "text": "[[Sozialhilfe]] wird Personen gewährt, die ihren Lebensunterhalt nicht aus eigener Kraft bestreiten können und die keinen oder unzureichenden Anspruch auf andere Leistungen wie [[Arbeitslosengeld]] oder [[Pension]] haben"}, {"kategorie": "", "text": "Die Sozialhilfeträger stellen sicher, dass diese Personen die notwendige finanzielle Unterstützung erhalten, um ihren Lebensunterhalt, ihre Gesundheit und ein menschenwürdiges Leben zu sichern"}, {"kategorie": "", "text": "Aufgaben des Sozialhilfeträgers:  (i) Existenzsicherung: Unterstützung bei Kosten für Wohnen, Nahrung und Kleidung;  (ii) Gesundheitsversorgung: Deckung von Krankheitskosten, die nicht von anderen Versicherungen getragen werden;  (iii) Pflegekosten: Unterstützung bei Pflegebedürftigkeit, wenn das [[Pflegegeld]] oder eigene Mittel nicht ausreichen;  (iv) Unterstützung in besonderen Notlagen: Hilfe bei akuten finanziellen Notlagen;  (v) Bedürftigkeit: Sozialhilfeträger leisten Hilfe auf Grundlage des Bedarfs der betroffenen Personen. Um Unterstützung zu erhalten, muss die Person nachweisen, dass sie bedürftig ist und keinen ausreichenden Zugang zu anderen sozialen Sicherungssystemen hat"}, {"kategorie": "", "text": "In Österreich ist die Sozialhilfe durch das Sozialhilfegesetz geregelt. Die Umsetzung und Verteilung der Leistungen erfolgt durch die [[Bundesländer]]. Die Sozialhilfeträger unterliegen den regionalen Vorschriften und Regelungen, was zu unterschiedlichen Ausgestaltungen der Sozialhilfe in den einzelnen Bundesländern führen kann"}, {"kategorie": "", "text": "Um [[Sozialhilfeleistungen]] zu erhalten, muss ein Antrag bei dem zuständigen Sozialhilfeträger gestellt werden. Die Bedürftigkeit der Antragsteller wird geprüft, und es werden Einkommens- und Vermögensverhältnisse berücksichtigt, um die Höhe der Hilfe festzulegen"}, {"kategorie": "", "text": "Sozialhilfeträger sind in Österreich in der Regel die [[Bundesländer]] oder Kommunen. Sie tragen die Verantwortung für die Durchführung der Sozialhilfe und gewährleisten, dass Hilfsbedürftige Zugang zu den notwendigen Leistungen erhalten."}]'::jsonb, ''),
  ('sozialvasicherungstraege', 'Sozialvasicherungsträge', '', '', '', '', 'Sozialversicherungsträger', '[{"kategorie": "jur.", "text": "\"öffentliche oder öffentlich-rechtliche Institution, die in Österreich für die Durchführung der [[Sozialversicherung]] verantwortlich ist\""}, {"kategorie": "", "text": "Die Sozialversicherungsträger erheben Beiträge, verwalten die finanziellen Mittel und gewähren Versicherungsleistungen in den Bereichen Krankenversicherung, Unfallversicherung, Pensionsversicherung und teilweise auch Pflegeversicherung"}, {"kategorie": "", "text": "Sie sorgen dafür, dass versicherte Personen im Krankheitsfall, bei Unfällen, im Alter oder bei Pflegebedürftigkeit finanziell abgesichert sind"}, {"kategorie": "", "text": "Der Sozialversicherungsträger ist dafür zuständig, die Beiträge der Versicherten und Arbeitgeber zu verwalten und daraus finanzielle Leistungen zu erbringen, wenn bestimmte Versicherungsfälle eintreten (z. B. Krankheit, Unfall, Alter, Pflegebedürftigkeit). Dazu zählen:  (i) [[Krankengeld]], [[Pflegegeld]], [[Unfallrenten]] oder [[Pensionszahlungen]];  (ii) \n[[Gesundheitsleistungen]], wie ärztliche Behandlungen oder Krankenhausaufenthalte;  (iii) [[Rehabilitationsleistungen]] nach Unfällen oder Krankheiten"}, {"kategorie": "", "text": "Bereiche der Sozialversicherung: (i) [[Krankenversicherung]]: Absicherung im Krankheitsfall und Finanzierung medizinischer Leistungen;  (ii) [[Unfallversicherung]]: Absicherung bei [[Arbeitsunfällen]] und [[Berufskrankheiten]];  (iii) Pensionsversicherung: Gewährleistung der [[Alters-]] und [[Invaliditätspension]];  (iii) [[Pflegeversicherung]]: Gewährung von [[Pflegegeld]]"}, {"kategorie": "", "text": "Die Sozialversicherungsträger finanzieren sich durch Beiträge, die von den Versicherten (meist Arbeitnehmern) und deren Arbeitgebern gezahlt werden. Die Höhe der Beiträge richtet sich in der Regel nach dem Einkommen der Versicherten"}, {"kategorie": "", "text": "Arten von Sozialversicherungsträgern:  (i) Österreichische Gesundheitskasse (ÖGK): Sie ist für die Krankenversicherung von Arbeitnehmern und deren Angehörigen zuständig;  (ii) Pensionsversicherungsanstalt (PVA): Diese Trägerinstitution verwaltet die Alters-, Invaliditäts- und Hinterbliebenenpensionen;  (iii) Allgemeine Unfallversicherungsanstalt (AUVA): Zuständig für Unfallversicherungen, insbesondere bei Arbeitsunfällen oder Berufskrankheiten"}, {"kategorie": "", "text": "Zu den Versicherten gehören Arbeitnehmer, Selbstständige, Beamte, Pensionisten und deren Angehörige. Die Art der Zugehörigkeit zu einem bestimmten Sozialversicherungsträger hängt oft vom Beruf oder der beruflichen Tätigkeit ab"}, {"kategorie": "", "text": "Die Tätigkeiten und Aufgaben der Sozialversicherungsträger sind im österreichischen [[Sozialversicherungsrecht]] verankert. Die Träger unterliegen der staatlichen Aufsicht und handeln nach den gesetzlichen Bestimmungen."}]'::jsonb, ''),
  ('kindesuntahoit', 'Kindesuntahoit', '', '', '', '', 'Kindesunterhalt', '[{"kategorie": "jur.", "text": "\"finanzielle Unterstützung, die Eltern ihrem Kind zur Deckung des täglichen Lebensbedarfs leisten müssen, solange das Kind nicht selbst in der Lage ist, für seinen Lebensunterhalt aufzukommen\""}, {"kategorie": "", "text": "In der Regel besteht der Kindesunterhalt bis zur Selbsterhaltungsfähigkeit des Kindes, also bis es die Ausbildung abgeschlossen hat und ein eigenes Einkommen erzielt"}, {"kategorie": "", "text": "Der Kindesunterhalt kann in Form von [[Naturalunterhalt]] (z. B. durch Pflege, Betreuung, Wohnen und Verpflegung) oder [[Barunterhalt]] (regelmäßige Geldzahlungen) erbracht werden"}, {"kategorie": "", "text": "Beide Elternteile sind grundsätzlich dazu verpflichtet, für den Unterhalt ihrer Kinder aufzukommen. Der Elternteil, bei dem das Kind lebt, leistet in der Regel Naturalunterhalt (Wohnung, Verpflegung, Betreuung), während der andere Elternteil, oft nach einer Trennung, Barunterhalt zahlt"}, {"kategorie": "", "text": "Der Unterhalt richtet sich in Österreich nach dem Einkommen des unterhaltspflichtigen Elternteils. Es gelten bestimmte Prozentsätze des Nettoeinkommens, die je nach Alter des Kindes variieren: (i) 16 % des Nettoeinkommens für Kinder von 0 bis 6 Jahren,  (ii) 18 % für Kinder von 7 bis 14 Jahren,  (iii) 20 % für Kinder ab 15 Jahren bis zur Selbsterhaltungsfähigkeit. Es können auch Anpassungen erfolgen, wenn der Elternteil weitere Unterhaltsverpflichtungen gegenüber anderen Kindern oder Personen hat"}, {"kategorie": "", "text": "Die Unterhaltspflicht endet, wenn das Kind selbsterhaltungsfähig ist, also ein eigenes Einkommen erzielt, das seinen Lebensunterhalt deckt. Dies ist in der Regel nach dem Abschluss einer Ausbildung der Fall. Bei Kindern, die studieren oder sich in einer längeren Ausbildung befinden, kann der Unterhalt bis zum Abschluss dieser Ausbildung gewährt werden"}, {"kategorie": "", "text": "Der Unterhaltsanspruch des Kindes kann gerichtlich festgelegt und in Form eines [[Unterhaltstitels]] durchgesetzt werden. Wenn der unterhaltspflichtige Elternteil nicht zahlt, können [[Zwangsvollstreckungsmaßnahmen]] wie [[Lohnpfändung]] eingeleitet werden"}, {"kategorie": "", "text": "Falls der unterhaltspflichtige Elternteil nicht zahlt oder zahlungsunfähig ist, kann das Kind in Österreich Anspruch auf einen [[Unterhaltsvorschuss]] vom [[Staat]] geltend machen. Dieser wird vom Staat ausgezahlt, und der Staat versucht anschließend, das Geld vom unterhaltspflichtigen Elternteil zurückzufordern."}]'::jsonb, ''),
  ('oetanuntahoit', 'Ötanuntahoit', '', '', '', '', 'Elternunterhalt', '[{"kategorie": "jur.", "text": "\"gesetzliche Verpflichtung erwachsener Kinder, ihre Eltern finanziell zu unterstützen, wenn diese ihren Lebensunterhalt nicht aus eigenen Mitteln bestreiten können\""}, {"kategorie": "", "text": "Dieser Anspruch entsteht in der Regel dann, wenn die Eltern pflegebedürftig sind und die eigenen Einkünfte oder das Vermögen nicht ausreichen, um die Kosten für ihren Unterhalt, insbesondere für Pflege, zu decken"}, {"kategorie": "", "text": "Der Elternunterhalt ist im österreichischen Familienrecht geregelt und basiert auf dem Prinzip des gegenseitigen Beistands in familiären Beziehungen. So wie Eltern verpflichtet sind, für ihre Kinder zu sorgen, besteht umgekehrt auch die Pflicht, dass erwachsene Kinder bei Bedarf zum Unterhalt ihrer Eltern beitragen"}, {"kategorie": "", "text": "Eltern haben einen Anspruch auf Unterhalt von ihren Kindern, wenn sie bedürftig sind, d. h., wenn sie ihren Lebensunterhalt oder Pflegekosten nicht mehr selbst finanzieren können. Die Bedürftigkeit tritt häufig bei Rentnern oder Pflegebedürftigen auf, die hohe Pflege- oder Heimkosten haben"}, {"kategorie": "", "text": "Der Anspruch auf Elternunterhalt hängt auch von der finanziellen Leistungsfähigkeit der Kinder ab. Nur wenn das Kind finanziell in der Lage ist, den Elternunterhalt zu leisten, kann es dazu herangezogen werden. Es wird dabei ein Selbstbehalt berücksichtigt, der sicherstellen soll, dass das Kind seinen eigenen Lebensunterhalt und den seiner Familie weiterhin bestreiten kann"}, {"kategorie": "", "text": "Der Elternunterhalt wird auf Basis des Einkommens und Vermögens des Kindes berechnet. Dabei werden in der Regel nur die Einkünfte oberhalb eines gewissen Selbstbehalts für den Unterhalt herangezogen. Das Einkommen des unterhaltsverpflichteten Kindes wird also nur soweit berücksichtigt, wie es für den eigenen Lebensbedarf nicht notwendig ist"}, {"kategorie": "", "text": "Der Elternunterhalt wird oft dann relevant, wenn die Eltern pflegebedürftig sind und die Kosten für die Pflege, etwa in einem Pflegeheim, nicht vollständig durch ihre Rente, Pflegegeld oder ihr Vermögen gedeckt werden können"}, {"kategorie": "", "text": "Wenn Eltern Sozialleistungen, wie z. B. Sozialhilfe oder Pflegegeld, erhalten, kann der Staat die erwachsenen Kinder zur Zahlung des Elternunterhalts heranziehen, um die öffentlichen Mittel zu entlasten. Der Sozialhilfeträger kann in solchen Fällen den Elternunterhalt direkt von den Kindern einfordern."}]'::jsonb, ''),
  ('ehegattnuntahoit', 'Ehegattnuntahoit', '', '', '', '', 'Ehegattenunterhalt', '[{"kategorie": "jur.", "text": "\"finanzielle Unterstützung, die ein Ehepartner dem anderen entweder während der Ehe oder nach einer Trennung bzw. Scheidung gewähren muss, wenn einer der Ehepartner bedürftig und der andere finanziell leistungsfähig ist\""}, {"kategorie": "", "text": "Der Unterhalt dient dazu, den Lebensstandard des bedürftigen Ehepartners aufrechtzuerhalten und wirtschaftliche Ungleichheiten, die durch die Ehe oder Scheidung entstanden sind, auszugleichen"}, {"kategorie": "", "text": "Es gibt folgende Formen des Ehegattenunterhalts:  (i) Unterhalt während der Ehe: Während der Ehe haben Ehepartner in Österreich die Pflicht, einander zu unterstützen und gemeinsam für den Lebensunterhalt der Familie aufzukommen. Dies kann durch Einkommen, Haushaltsführung oder Kinderbetreuung geschehen. Wenn ein Ehepartner nicht über ausreichende finanzielle Mittel verfügt, kann er von dem besserverdienenden Partner Unterhalt verlangen;  (ii) Unterhalt nach der Scheidung: Nach einer Scheidung kann ein Ehepartner Anspruch auf nachehelichen Unterhalt haben. Dieser Unterhalt hängt von verschiedenen Faktoren ab, insbesondere von der wirtschaftlichen Situation der Ehepartner und dem Scheidungsgrund;  (iii) Anspruch auf [[Trennungsunterhalt]]: Bereits während des Getrenntlebens haben Ehepartner unter bestimmten Voraussetzungen Anspruch auf Trennungsunterhalt, bis die Scheidung rechtskräftig ist. Dieser richtet sich nach den Lebensverhältnissen während der Ehe und soll sicherstellen, dass der bedürftige Ehepartner auch während der Trennung finanziell abgesichert ist;  (iv) [[Verschuldensunterhalt]]: Wenn die Scheidung aufgrund des alleinigen Verschuldens eines Partners erfolgt, kann der schuldlose Ehepartner unbefristeten Unterhalt verlangen;  (vi) Billigkeitsunterhalt: Bei Scheidung ohne Schuldzuweisung kann es einen Anspruch auf Unterhalt \"aus Billigkeit\" geben, z. B. wenn ein Partner wegen der Kinderbetreuung nicht voll arbeiten kann"}, {"kategorie": "", "text": "Der Unterhalt wird in der Regel auf Basis des Einkommens des unterhaltspflichtigen Ehepartners berechnet. Üblich ist, dass etwa 40 % des gemeinsamen Nettoeinkommens dem bedürftigen Ehepartner zustehen, abzüglich des eigenen Einkommens des Berechtigten"}, {"kategorie": "", "text": "Der Unterhaltsanspruch besteht nur, wenn der unterhaltspflichtige Partner finanziell in der Lage ist, Unterhalt zu zahlen, ohne selbst in Not zu geraten. Dabei wird ein Selbstbehalt berücksichtigt, der sicherstellt, dass der Pflichtige seine eigenen Lebenshaltungskosten decken kann"}, {"kategorie": "", "text": "Die Dauer des nachehelichen Unterhalts ist abhängig von den Umständen der Scheidung. Er kann befristet oder unbefristet gewährt werden, je nachdem, ob der bedürftige Ehepartner Aussicht auf eine berufliche Wiedereingliederung hat oder ob andere Umstände vorliegen, die eine längere Unterstützung erforderlich machen"}, {"kategorie": "", "text": "Der Ehegattenunterhalt kann angepasst werden, wenn sich die finanzielle Lage der beteiligten Personen ändert, z. B. durch Arbeitslosigkeit, eine neue Ehe oder eine erhebliche Änderung des Einkommens."}]'::jsonb, ''),
  ('vaschuidnsuntahoit', 'Vaschuidnsuntahoit', '', '', '', '', 'Verschuldensunterhalt', '[{"kategorie": "jur.", "text": "\"nachehelicher Unterhalt, den ein Ehepartner nach der Scheidung erhalten kann, wenn die Scheidung ausschließlich oder überwiegend durch das Verschulden des anderen Ehepartners verursacht wurde\""}, {"kategorie": "", "text": "In diesem Fall ist der schuldige Partner verpflichtet, dem unschuldigen Partner Unterhalt zu zahlen"}, {"kategorie": "", "text": "Der Anspruch auf Verschuldensunterhalt entsteht, wenn einem Ehepartner im [[Scheidungsverfahren]] die alleinige oder überwiegende Schuld an der Zerrüttung der Ehe zugewiesen wird. Gründe für eine Scheidung aus Verschulden können etwa Ehebruch, Gewalt, schwere Kränkungen oder ein nachhaltiges Verlassen der gemeinsamen Ehewohnung sein"}, {"kategorie": "", "text": "Der unschuldige Ehepartner hat Anspruch auf Unterhalt, um seinen bisherigen Lebensstandard nach der Scheidung aufrechtzuerhalten, wenn er finanziell bedürftig ist und der schuldige Partner leistungsfähig genug ist, den Unterhalt zu zahlen"}, {"kategorie": "", "text": "Die Höhe des Verschuldensunterhalts wird auf Basis des Einkommens des unterhaltspflichtigen Partners berechnet. In der Regel erhält der berechtigte Partner 40 % des gemeinsamen Nettoeinkommens, wobei das eigene Einkommen des Berechtigten abgezogen wird"}, {"kategorie": "", "text": "Der Verschuldensunterhalt kann auf unbestimmte Zeit zugesprochen werden, insbesondere wenn der unschuldige Partner aufgrund der Ehe eine finanzielle Benachteiligung erlitten hat (z. B. durch Aufgabe des Berufs für die Kindererziehung). Der Anspruch besteht so lange, bis der Berechtigte in der Lage ist, seinen Lebensunterhalt selbst zu bestreiten, oder bis andere Umstände eintreten (z. B. neue Ehe oder eingetragene Partnerschaft)"}, {"kategorie": "", "text": "Der schuldige Ehepartner muss nur dann Verschuldensunterhalt zahlen, wenn er dazu finanziell in der Lage ist. Auch hier wird ein Selbstbehalt berücksichtigt, der sicherstellt, dass der unterhaltspflichtige Partner seine eigenen Lebenshaltungskosten decken kann"}, {"kategorie": "", "text": "Der Verschuldensunterhalt kann angepasst oder beendet werden, wenn sich die Umstände ändern, z. B. durch eine erhebliche Veränderung der finanziellen Verhältnisse, Wiederverheiratung des Berechtigten oder einen Wegfall der Bedürftigkeit."}]'::jsonb, ''),
  ('trennungsunterhalt', 'Trennungsunterhalt', '', '', '', '', 'Trennungsunterhalt', '[{"kategorie": "jur.", "text": "\"finanzielle Unterstützung, die ein Ehepartner dem anderen während der Trennungsphase, aber noch vor der rechtskräftigen [[Scheidung]], leisten muss, wenn dieser bedürftig ist\""}, {"kategorie": "", "text": "Der Trennungsunterhalt dient dazu, den wirtschaftlich schwächeren Partner während des Getrenntlebens finanziell abzusichern und ihm einen angemessenen Lebensstandard zu ermöglichen, bis das Scheidungsverfahren abgeschlossen ist"}, {"kategorie": "", "text": "Der Trennungsunterhalt wird während des Getrenntlebens gezahlt, solange die Ehe rechtlich noch besteht, aber die Ehepartner nicht mehr zusammenleben. Der Anspruch endet in der Regel mit der Scheidung, danach kann ggf. [[nachehelicher]] Unterhalt beansprucht werden"}, {"kategorie": "", "text": "Ein Anspruch auf Trennungsunterhalt besteht, wenn ein Ehepartner während der Trennung bedürftig ist und der andere finanziell in der Lage ist, Unterhalt zu leisten. Die Bedürftigkeit ergibt sich häufig daraus, dass ein Ehepartner weniger verdient oder sich um den gemeinsamen Haushalt oder die Kindererziehung gekümmert hat"}, {"kategorie": "", "text": "Die Höhe des Trennungsunterhalts richtet sich nach dem gemeinsamen Lebensstandard während der Ehe und dem Einkommen des unterhaltspflichtigen Partners. In der Regel werden 40 % des gemeinsamen Nettoeinkommens als Berechnungsgrundlage angesetzt, wobei das eigene Einkommen des bedürftigen Partners angerechnet wird"}, {"kategorie": "", "text": "Der Trennungsunterhalt wird nur gezahlt, wenn der unterhaltspflichtige Ehepartner finanziell in der Lage ist, diesen zu leisten. Ein Selbstbehalt wird berücksichtigt, um sicherzustellen, dass der unterhaltspflichtige Partner seine eigenen Lebenshaltungskosten decken kann"}, {"kategorie": "", "text": "Im Gegensatz zum nachehelichen [[Verschuldensunterhalt]] spielt die Frage, wer die Trennung verschuldet hat, beim Trennungsunterhalt keine Rolle. Die Zahlung des Unterhalts richtet sich ausschließlich nach den Bedürfnissen des einen Partners und der Leistungsfähigkeit des anderen"}, {"kategorie": "", "text": "Der Anspruch auf Trennungsunterhalt besteht bis zur rechtskräftigen Scheidung. Danach kann, abhängig von der Scheidungsregelung und den Umständen, nachehelicher Unterhalt gewährt werden."}]'::jsonb, ''),
  ('naturaluntahoit', 'Naturaluntahoit', '', '', '', '', 'Naturalunterhalt', '[{"kategorie": "jur.", "text": "\"Form der Unterhaltsleistung, bei der der [[Unterhalt]] nicht in Geld, sondern durch die direkte Bereitstellung von Gütern und Dienstleistungen erbracht wird, die der unterhaltsberechtigten Person zur Deckung ihres täglichen Lebensbedarfs dienen\""}, {"kategorie": "", "text": "Dazu gehören beispielsweise Wohnung, Verpflegung, Kleidung, Bildung und Betreuung. Der Naturalunterhalt ist vor allem im Zusammenhang mit Kindern relevant, insbesondere wenn ein Elternteil das Kind betreut und versorgt"}, {"kategorie": "", "text": "In der Regel leistet der Elternteil, bei dem das Kind lebt, den Naturalunterhalt, indem er für die tägliche Versorgung des Kindes sorgt, während der andere Elternteil den Barunterhalt zahlt (regelmäßige Geldzahlungen)"}, {"kategorie": "", "text": "Beispiele für Naturalunterhalt:  (i) Wohnung und Unterkunft: Bereitstellung eines Wohnraums für das Kind;  (ii) Verpflegung: Bereitstellung von Nahrung und Getränken;  (iii) Kleidung und persönliche Versorgung: Sorge für Kleidung und notwendige persönliche Gegenstände;  (iv) Betreuung und Erziehung: Zeit und Aufmerksamkeit, die dem Kind in Form von Pflege, Erziehung und Aufsicht gewidmet wird"}, {"kategorie": "", "text": "Unterscheidung zum [[Barunterhalt]]: Während der Barunterhalt durch finanzielle Zahlungen erbracht wird, um den Lebensunterhalt zu sichern, wird der Naturalunterhalt durch direkte Sach- und Dienstleistungen geleistet. Beide Formen ergänzen sich in der Regel, insbesondere bei getrennt lebenden Elternteilen"}, {"kategorie": "", "text": "Auch bei Ehegatten kann Naturalunterhalt eine Rolle spielen, z. B. wenn ein Ehepartner durch Haushaltsführung, Kinderbetreuung oder die Bereitstellung von Unterkunft zur Deckung der gemeinsamen Bedürfnisse beiträgt"}, {"kategorie": "", "text": "Der Naturalunterhalt ist gesetzlich vorgesehen, insbesondere im Familienrecht. Eltern haben die Verpflichtung, sowohl durch Natural- als auch Barunterhalt für ihre Kinder zu sorgen, abhängig davon, wie das Leben und die Betreuung organisiert sind."}]'::jsonb, ''),
  ('baruntahoit', 'Baruntahoit', '', '', '', '', 'Barunterhalt', '[{"kategorie": "jur.", "text": "\"finanzielle Unterstützung, die der unterhaltspflichtige Elternteil zur Deckung des Lebensbedarfs einer unterhaltsberechtigten Person, meist eines Kindes, in Geldform leistet\""}, {"kategorie": "", "text": "Im Gegensatz zum [[Naturalunterhalt]], der durch direkte Sachleistungen wie Wohnung, Verpflegung und Betreuung erbracht wird, erfolgt der Barunterhalt durch regelmäßige Geldzahlungen an die unterhaltsberechtigte Person oder deren gesetzlichen Vertreter, etwa den Elternteil, bei dem das Kind lebt"}, {"kategorie": "", "text": "Der Barunterhalt besteht aus regelmäßig gezahlten Geldbeträgen, die zur Deckung des Lebensbedarfs des Kindes oder des unterhaltsberechtigten Ehepartners dienen. Diese Beträge sollen Kosten für Nahrung, Kleidung, Ausbildung, Freizeit, Gesundheit und andere alltägliche Bedürfnisse abdecken"}, {"kategorie": "", "text": "[[Kindesunterhalt]]: Bei getrennt lebenden Eltern leistet der Elternteil, bei dem das Kind nicht lebt, in der Regel den Barunterhalt, während der andere Elternteil, bei dem das Kind wohnt, den Naturalunterhalt übernimmt (z. B. durch Betreuung und Verpflegung). Der Barunterhalt stellt somit die finanzielle Absicherung des Kindes sicher"}, {"kategorie": "", "text": "Der Barunterhalt wird auf Basis des Einkommens des unterhaltspflichtigen Elternteils berechnet. In Österreich gibt es für den Kindesunterhalt feste Prozentsätze des Nettoeinkommens, die je nach Alter des Kindes variieren:  (i) 16 % für Kinder von 0 bis 6 Jahren,  (ii) 18 % für Kinder von 7 bis 14 Jahren,  (iii) 20 % für Kinder ab 15 Jahren bis zur Selbsterhaltungsfähigkeit"}, {"kategorie": "", "text": "Der Barunterhalt wird nur dann geschuldet, wenn der unterhaltspflichtige Elternteil finanziell leistungsfähig ist. Dabei wird ein Selbstbehalt berücksichtigt, der sicherstellt, dass der Pflichtige seinen eigenen Lebensunterhalt decken kann"}, {"kategorie": "", "text": "Der Barunterhalt wird in der Regel bis zur Selbsterhaltungsfähigkeit des Kindes gezahlt, also bis das Kind in der Lage ist, seinen eigenen Lebensunterhalt zu bestreiten. Das kann über die Volljährigkeit hinaus der Fall sein, z. B. wenn das Kind noch in Ausbildung oder im Studium ist"}, {"kategorie": "", "text": "Wenn der unterhaltspflichtige Elternteil den Barunterhalt nicht freiwillig zahlt, kann der [[Unterhaltsanspruch]] gerichtlich geltend gemacht werden. In diesem Fall wird der [[Unterhaltstitel]] vollstreckbar, und es können Zwangsmaßnahmen wie [[Lohnpfändung]] eingeleitet werden."}]'::jsonb, ''),
  ('pflegegoeoed', 'Pflegegööd', '', '', '', '', 'Pflegegeld', '[{"kategorie": "jur.", "text": "\"finanzielle Leistung des Staates, die in Österreich Personen gewährt wird, die aufgrund einer körperlichen oder geistigen Behinderung, Krankheit oder Pflegebedürftigkeit regelmäßige Unterstützung und Pflege benötigen\""}, {"kategorie": "", "text": "Das Pflegegeld soll dazu beitragen, die Kosten für die erforderliche Betreuung und Pflege zu decken und die Selbstständigkeit und Lebensqualität der pflegebedürftigen Person zu erhalten. Es wird unabhängig vom Einkommen und Vermögen der betroffenen Person gezahlt"}, {"kategorie": "", "text": "Anspruch auf Pflegegeld haben Personen, die aufgrund einer dauerhaften Beeinträchtigung ihres körperlichen oder geistigen Zustands auf Pflege und Hilfe angewiesen sind. Der Pflegebedarf muss voraussichtlich für mindestens sechs Monate bestehen, und es muss ein bestimmtes Ausmaß an Pflegeaufwand vorliegen, das durch die Pflegeeinstufung festgelegt wird"}, {"kategorie": "", "text": "Pflegestufen: Das Pflegegeld ist in sieben Stufen gestaffelt, die sich nach dem Umfang des Pflegebedarfs richten. Je höher der Pflegeaufwand, desto höher die Pflegestufe und der entsprechende Geldbetrag:  (i) Stufe 1: ab 65 Stunden Pflegebedarf pro Monat;  (ii) Stufe 2: ab 95 Stunden;  (iii) Stufe 3: ab 120 Stunden;  (iv) Stufe 4: ab 160 Stunden;  (v) Stufe 5: ab 180 Stunden mit außergewöhnlichem Pflegeaufwand;  (vi) Stufe 6: ab 180 Stunden, wenn dauernde Betreuung erforderlich ist;  (vii) Stufe 7: ab 180 Stunden, wenn keine zielgerichteten Bewegungen der Extremitäten mehr möglich sind"}, {"kategorie": "", "text": "Die Höhe des Pflegegeldes hängt von der Pflegestufe ab. Je nach Einstufung erhalten pflegebedürftige Personen einen monatlichen Geldbetrag, der zur Unterstützung ihrer Pflege und Betreuung verwendet werden kann"}, {"kategorie": "", "text": "Das Pflegegeld ist zweckgebunden und soll für pflegerische Leistungen verwendet werden. Es kann eingesetzt werden, um die Pflege durch Angehörige, professionelle Pflegedienste oder den Aufenthalt in Pflegeeinrichtungen zu finanzieren"}, {"kategorie": "", "text": "Antrag und Gewährung: Das Pflegegeld muss bei der zuständigen Behörde (z. B. [[Sozialversicherungsträger]] oder [[Pensionsversicherungsanstalt]]) beantragt werden. Der Pflegebedarf wird von einem medizinischen Sachverständigen geprüft, der die Einstufung in die entsprechende Pflegestufe vornimmt."}]'::jsonb, ''),
  ('untahoitsaunschbruch', 'Untahoitsaunschbruch', '', '', '', '', 'Unterhaltsanspruch', '[{"kategorie": "jur.", "text": "\"gesetzliches Recht einer Person, von einer anderen Person regelmäßige finanzielle Unterstützung zu erhalten, um den eigenen Lebensunterhalt zu bestreiten\""}, {"kategorie": "", "text": "Der Unterhaltsanspruch entsteht in der Regel in familiären Beziehungen, wie zwischen Eltern und Kindern oder zwischen Ehepartnern, und wird durch das Gesetz geregelt"}, {"kategorie": "", "text": "Der Zweck des Unterhaltsanspruchs besteht darin, sicherzustellen, dass bedürftige Personen ausreichend versorgt sind, wenn sie ihren Lebensunterhalt nicht selbst decken können"}, {"kategorie": "", "text": "Der Unterhaltsanspruch ist gesetzlich verankert und kann in verschiedenen familiären Beziehungen bestehen, wie:  (i) Kindesunterhalt: Kinder haben gegenüber ihren Eltern einen Unterhaltsanspruch bis zur Selbsterhaltungsfähigkeit, also in der Regel bis zum Abschluss der Ausbildung;  (ii) Ehegattenunterhalt: Ehepartner haben während und nach der Ehe einen gegenseitigen Unterhaltsanspruch, insbesondere nach einer Trennung oder Scheidung;  (iii) Elternunterhalt: In bestimmten Fällen haben Eltern gegenüber ihren erwachsenen Kindern einen Unterhaltsanspruch, wenn sie nicht in der Lage sind, ihren eigenen Lebensunterhalt zu bestreiten"}, {"kategorie": "", "text": "Damit ein Unterhaltsanspruch besteht, müssen bestimmte Bedingungen erfüllt sein: (i) Bedürftigkeit: Die unterhaltsberechtigte Person muss in der Regel bedürftig sein, d. h., sie muss außerstande sein, ihren Lebensunterhalt selbst zu finanzieren;  (ii) Leistungsfähigkeit: Der Unterhaltspflichtige muss finanziell in der Lage sein, den Unterhalt zu leisten, ohne selbst in Not zu geraten;  (iii) Höhe des Unterhalts: Der Unterhaltsanspruch wird in der Regel auf Basis des Einkommens des Unterhaltspflichtigen berechnet. Für den Kindesunterhalt gibt es in Österreich Prozentsätze, die je nach Alter des Kindes und Höhe des Einkommens angewandt werden. Beim Ehegattenunterhalt wird die Höhe individuell festgelegt und hängt von der Lebenssituation und dem Einkommen der Ehepartner ab"}, {"kategorie": "", "text": "Die Dauer des Unterhaltsanspruchs hängt von der Art des Unterhalts ab:  (i) Kindesunterhalt: Bis zur Selbsterhaltungsfähigkeit des Kindes, das heißt meist bis zum Ende der Ausbildung;  (ii) Ehegattenunterhalt: Während der Ehe und, je nach Fall, auch nach der Scheidung, wobei Faktoren wie Dauer der Ehe, Alter und Bedürftigkeit berücksichtigt werden"}, {"kategorie": "", "text": "Der Unterhaltsanspruch kann durch einen [[Unterhaltstitel]] gerichtlich festgelegt und bei Nichtzahlung durch [[Zwangsvollstreckung]], wie [[Lohnpfändung]] oder [[Kontopfändung]], durchgesetzt werden"}, {"kategorie": "", "text": "Der Unterhaltsanspruch kann sich im Laufe der Zeit ändern, etwa wenn sich das Einkommen oder die Lebenssituation des Unterhaltspflichtigen oder des Berechtigten ändert. Es ist möglich, den Unterhalt gerichtlich anpassen zu lassen."}]'::jsonb, ''),
  ('untahoit', 'Untahoit', '', '', '', '', 'Unterhalt', '[{"kategorie": "jur.", "text": "\"gesetzlich oder vertraglich festgelegte finanzielle Unterstützung, die eine Person (der Unterhaltspflichtige) einer anderen Person (dem Unterhaltsberechtigten) zur Deckung ihres Lebensbedarfs leisten muss\""}, {"kategorie": "", "text": "Unterhaltsverpflichtungen bestehen in der Regel zwischen nahen Angehörigen, wie Eltern und Kindern oder Ehepartnern, und sollen sicherstellen, dass der Lebensunterhalt der unterhaltsberechtigten Person gedeckt ist, wenn diese ihren Bedarf nicht aus eigener Kraft bestreiten kann"}, {"kategorie": "", "text": "Arten von Unterhalt: (i) [[Kindesunterhalt]]: Eltern sind verpflichtet, ihre Kinder finanziell zu unterstützen, bis diese selbsterhaltungsfähig sind. Das umfasst in der Regel den Zeitraum bis zum Abschluss der Erstausbildung oder des Studiums;  (ii) \n[[Ehegattenunterhalt]]: Ehegatten können während und nach der Ehe zur gegenseitigen finanziellen Unterstützung verpflichtet sein, insbesondere nach einer Trennung oder Scheidung. Es gibt sowohl Trennungsunterhalt (während des Trennungszeitraums) als auch nachehelichen Unterhalt (nach der Scheidung);  (iii) [[Elternunterhalt]]: In bestimmten Fällen sind erwachsene Kinder verpflichtet, ihre Eltern finanziell zu unterstützen, wenn diese ihren Lebensunterhalt nicht aus eigenen Mitteln bestreiten können"}, {"kategorie": "", "text": "Der Unterhalt wird in der Regel auf Grundlage des Einkommens des Unterhaltspflichtigen berechnet. Beim Kindesunterhalt richtet sich der Betrag oft nach Prozentsätzen des Nettoeinkommens und hängt vom Alter des Kindes und eventuellen weiteren Unterhaltspflichten ab. Beim Ehegattenunterhalt berücksichtigt das Gericht Faktoren wie die Dauer der Ehe, das Einkommen und die Bedürftigkeit des Ehepartners"}, {"kategorie": "", "text": "Unterhalt kann entweder durch [[Naturalunterhalt]] (z. B. durch Betreuung, Erziehung, Verpflegung und Unterkunft) oder durch [[Barunterhalt]] (regelmäßige Geldzahlungen) geleistet werden. Bei getrennt lebenden Eltern erbringt in der Regel der Elternteil, bei dem das Kind nicht lebt, den Barunterhalt"}, {"kategorie": "", "text": "Unterhaltsverpflichtungen bestehen, solange der Unterhaltsberechtigte bedürftig ist und der Unterhaltspflichtige leistungsfähig. Beim Kindesunterhalt gilt dies bis zur Selbsterhaltungsfähigkeit des Kindes, also in der Regel bis zum Abschluss der Ausbildung. Beim Ehegattenunterhalt kann der Anspruch auf nachehelichen Unterhalt abhängig von der Dauer der Ehe, dem Alter und der finanziellen Situation des bedürftigen Partners befristet oder unbefristet sein"}, {"kategorie": "", "text": "Der Unterhalt kann durch einen gerichtlichen [[Unterhaltstitel]] festgelegt und bei Bedarf durch [[Zwangsvollstreckungsmaßnahmen]], wie [[Lohn-]] oder [[Kontopfändung]], durchgesetzt werden, wenn der Unterhaltspflichtige nicht zahlt."}]'::jsonb, ''),
  ('untahoitstitl', 'Untahoitstitl', '', '', '', '', 'Unterhaltstitel', '[{"kategorie": "jur.", "text": "\"rechtsverbindliche Entscheidung oder Urkunde, die einen [[Unterhaltsanspruch]] rechtskräftig festlegt\""}, {"kategorie": "", "text": "Der Unterhaltstitel dient als rechtliche Grundlage dafür, dass der Unterhaltsberechtigte, beispielsweise ein Kind oder ein ehemaliger Ehepartner, den zugesprochenen Unterhalt einfordern und notfalls gerichtlich durchsetzen kann"}, {"kategorie": "", "text": "Der Unterhaltstitel enthält die Höhe des geschuldeten Unterhalts sowie eventuell weitere Regelungen, wie die Fälligkeit der Zahlungen"}, {"kategorie": "", "text": "Arten von Unterhaltstiteln:  (i) [[Gerichtsurteil]]: Ein gerichtlicher Unterhaltstitel entsteht durch ein Urteil eines Gerichts, das im Rahmen eines Unterhaltsverfahrens gefällt wurde;  (ii) [[Vergleich]]: Ein gerichtlicher Vergleich zwischen den Parteien, der vom Gericht genehmigt wird, stellt ebenfalls einen Unterhaltstitel dar;  (iii) Notarielle Urkunde: Ein Unterhaltstitel kann auch in Form einer notariell beglaubigten Vereinbarung vorliegen, die zwischen den Parteien abgeschlossen wurde"}, {"kategorie": "", "text": "Der Unterhaltstitel ist vollstreckbar, das bedeutet, der Berechtigte kann auf dessen Grundlage Zwangsvollstreckungsmaßnahmen einleiten, wenn der Unterhaltspflichtige nicht freiwillig zahlt. Dies kann beispielsweise durch eine [[Lohnpfändung]] oder [[Kontopfändung]] erfolgen"}, {"kategorie": "", "text": "Der Unterhaltstitel bleibt so lange in Kraft, bis er entweder erfüllt wurde (z. B. wenn das Kind selbsterhaltungsfähig wird) oder gerichtlich oder durch Vereinbarung abgeändert wird. Ein Unterhaltstitel kann geändert werden, wenn sich die finanziellen Verhältnisse des Unterhaltspflichtigen oder die Bedürfnisse des Unterhaltsberechtigten ändern"}, {"kategorie": "", "text": "Der Unterhaltstitel kann sowohl für Kindesunterhalt, Ehegattenunterhalt als auch Elternunterhalt erlassen werden, je nach Art des Unterhaltsanspruchs."}]'::jsonb, ''),
  ('untahoitsvafoan', 'Untahoitsvafoan', '', '', '', '', 'Unterhaltsverfahren', '[{"kategorie": "jur.", "text": "\"gerichtliches Verfahren, in dem der Anspruch auf [[Unterhalt]] für eine unterhaltsberechtigte Person, wie z. B. ein Kind oder ein geschiedener Ehepartner, festgestellt oder durchgesetzt wird\""}, {"kategorie": "", "text": "Das Verfahren wird angestrebt, wenn keine einvernehmliche Regelung über den Unterhalt erzielt werden kann oder wenn der Unterhaltspflichtige die Unterhaltszahlungen nicht leistet"}, {"kategorie": "", "text": "Ziel des Unterhaltsverfahrens ist es, den Anspruch einer Person auf finanzielle Unterstützung (Unterhalt) durch einen Unterhaltspflichtigen rechtlich festzustellen und den genauen Betrag zu bestimmen. Das Verfahren kann sowohl zur erstmaligen Festlegung von Unterhaltszahlungen als auch zur Durchsetzung bereits bestehender Ansprüche dienen"}, {"kategorie": "", "text": "Arten von Unterhalt:  (i) Kindesunterhalt: Der Anspruch eines Kindes gegenüber einem Elternteil auf finanzielle Unterstützung;  (ii) Ehegattenunterhalt: Der Anspruch eines Ehepartners auf Unterhalt nach einer Scheidung oder Trennung;  (iii) Elternunterhalt: Der Anspruch von Eltern gegenüber ihren Kindern in bestimmten Fällen, wenn sie selbst nicht für ihren Lebensunterhalt aufkommen können"}, {"kategorie": "", "text": "Das Verfahren wird in der Regel durch einen Antrag beim zuständigen [[Gericht]] eingeleitet. Die unterhaltsberechtigte Person oder deren gesetzlicher Vertreter beantragt die Festsetzung von Unterhalt"}, {"kategorie": "", "text": "Im Unterhaltsverfahren wird geprüft, wie viel Unterhalt geschuldet ist. Dabei werden das Einkommen und die finanzielle Leistungsfähigkeit des unterhaltspflichtigen Elternteils sowie der Bedarf des unterhaltsberechtigten Kindes oder Ehepartners berücksichtigt. Bei Kindern gibt es in vielen Ländern Leitlinien oder Tabellen zur Berechnung des Unterhalts"}, {"kategorie": "", "text": "Das Gericht entscheidet nach Prüfung aller relevanten Umstände über die Höhe und Dauer der Unterhaltszahlungen. Die Entscheidung wird als [[Unterhaltstitel]] bezeichnet und ist rechtlich bindend"}, {"kategorie": "", "text": "Falls der Unterhaltspflichtige die festgesetzten Zahlungen nicht leistet, kann der Unterhaltstitel im Rahmen der [[Zwangsvollstreckung]] durchgesetzt werden, z. B. durch [[Lohnpfändung]] oder [[Kontopfändung]]"}, {"kategorie": "", "text": "Falls sich die finanziellen Verhältnisse des Unterhaltspflichtigen oder die Bedürfnisse des Unterhaltsberechtigten ändern, kann eine Abänderung des Unterhaltstitels im Rahmen eines neuen Unterhaltsverfahrens beantragt werden."}]'::jsonb, '')
